**Optimized x64 “AOB” (Array‑of‑Bytes) pattern scanner**  
The code below is a single‑file, production‑ready implementation that:

* Takes a module base address and its size (obtained via `GetModuleInformation`).  
* Accepts a *signature* string (`"48 8B 05 ?? ?? ?? ?? 48 85 C0"`) and builds a byte‑array + mask (`xxxx????xxxx`).  
* Scans the module’s memory region with a tight inner loop that exits on the first mismatch.  
* (Optional) Shows how to accelerate the scan with a simple Boyer‑Moore‑Horspool‑like skip table – the table is built once and used for every candidate start position.  
* Returns the first matching address or `nullptr` if none is found.

The scanner works for any 64‑bit Windows module (EXE, DLL, etc.) and can be dropped into a trainer, cheat, or debugging tool.

---

## 1.  Full source (C++17, MSVC/GCC/Clang compatible)

```cpp
/******************************************************************************************
 *  AOB Pattern Scanner – x64 Windows
 *  --------------------------------------------------------------
 *  Author:  (you)
 *  License: MIT – feel free to use/modify.
 *
 *  Features
 *  --------
 *  • Parses a signature string with wildcards ("??").
 *  • Builds a byte pattern + mask (x = must match, ? = wildcard).
 *  • Scans a memory region using a tight loop with early‑out.
 *  • Optional Boyer‑Moore‑Horspool skip table for larger patterns (≥4 bytes).
 *  • Example usage: scan user32.dll for a known MessageBoxA prologue.
 *
 *  Build (MSVC):
 *      cl /EHsc /std:c++17 /O2 pattern_scanner.cpp
 *
 *  Build (gcc/clang):
 *      g++ -std=c++17 -O2 -Wall pattern_scanner.cpp -o pattern_scanner
 ******************************************************************************************/

#include <windows.h>
#include <vector>
#include <string>
#include <sstream>
#include <iostream>
#include <iomanip>
#include <algorithm>
#include <cstdint>
#include <cstring>   // for memcmp

/* -------------------------------------------------------------------------- */
/*  Helper: convert a signature string to pattern bytes + mask                */
/* -------------------------------------------------------------------------- */
struct PatternData {
    std::vector<uint8_t> bytes;   // pattern bytes (0 for wildcards)
    std::string          mask;    // same length, 'x' = check, '?' = ignore
};

/**
 * @brief Parse a signature like "48 8B 05 ?? ?? ?? ?? 48 85 C0"
 * @param sig  Signature string (bytes separated by spaces, wildcards as "??")
 * @return PatternData containing the byte array and mask.
 */
static PatternData ParsePattern(const std::string& sig)
{
    PatternData out;
    std::istringstream iss(sig);
    std::string token;

    while (iss >> token) {
        if (token == "??") {
            out.bytes.push_back(0);          // value irrelevant for wildcard
            out.mask.push_back('?');
        } else {
            // Expect a hex byte, e.g. "48" or "0A"
            if (token.size() != 2) {
                throw std::runtime_error("Invalid pattern token: " + token);
            }
            uint8_t b = static_cast<uint8_t>(
                std::stoul(token, nullptr, 16));
            out.bytes.push_back(b);
            out.mask.push_back('x');
        }
    }
    return out;
}

/* -------------------------------------------------------------------------- */
/*  Boyer‑Moore‑Horspool skip table (optional optimisation)                */
/* -------------------------------------------------------------------------- */
/**
 * @brief Build a skip table for the pattern (last‑occurrence heuristic).
 *        Only bytes that are *not* wildcards are considered.
 * @param pattern  PatternData (bytes+mask)
 * @return std::array<int,256> where table[c] = distance to shift when byte c mismatches.
 */
static std::array<int, 256> BuildSkipTable(const PatternData& pattern)
{
    const size_t patLen = pattern.bytes.size();
    std::array<int, 256> skip{};
    std::fill(skip.begin(), skip.end(), static_cast<int>(patLen)); // default shift = pattern length

    // Scan pattern from left to right, but we only care about the last non‑wildcard
    // occurrence of each byte (the classic Horspool rule).
    for (size_t i = 0; i < patLen - 1; ++i) { // skip the last byte – handled by main loop
        if (pattern.mask[i] == 'x') {
            uint8_t b = pattern.bytes[i];
            skip[b] = static_cast<int>(patLen - 1 - i);
        }
    }
    return skip;
}

/* -------------------------------------------------------------------------- */
/*  Core scanner                                                            */
/* -------------------------------------------------------------------------- */
/**
 * @brief Scan a memory region for a pattern.
 *
 * @param regionStart   Pointer to the first byte of the region to scan.
 * @param regionSize    Size of the region in bytes.
 * @param pattern       Pre‑parsed pattern (bytes+mask).
 * @param useSkipTable  If true, use Boyer‑Moore‑Horspool skipping (faster for long patterns).
 * @return Pointer to the first matching byte, or nullptr if not found.
 */
static void* ScanMemory(const void* regionStart,
                        SIZE_T regionSize,
                        const PatternData& pattern,
                        bool useSkipTable = true)
{
    if (!regionStart || regionSize == 0 || pattern.bytes.empty())
        return nullptr;

    const uint8_t* begin = static_cast<const uint8_t*>(regionStart);
    const uint8_t* end   = begin + regionSize;
    const size_t   patLen = pattern.bytes.size();

    if (regionSize < patLen)
        return nullptr;

    /* ----- Simple linear scan (fast enough for most cases) ----- */
    if (!useSkipTable || patLen < 4) {
        for (const uint8_t* cur = begin; cur <= end - patLen; ++cur) {
            bool ok = true;
            for (size_t i = 0; i < patLen; ++i) {
                if (pattern.mask[i] == 'x' && pattern.bytes[i] != cur[i]) {
                    ok = false;
                    break;
                }
            }
            if (ok)
                return const_cast<void*>(static_cast<const void*>(cur));
        }
        return nullptr;
    }

    /* ----- Boyer‑Moore‑Horspool variant (skip table) ----- */
    const auto skip = BuildSkipTable(pattern);
    const uint8_t* cur = begin + patLen - 1; // align to the last byte of the window

    while (cur < end) {
        size_t i = patLen;
        while (i > 0) {
            --i;
            if (pattern.mask[i] == 'x' && pattern.bytes[i] != cur[i]) {
                // Mismatch – shift according to the byte that caused the mismatch
                uint8_t badByte = cur[i];
                cur += std::max<int>(1, skip[badByte]);
                goto outer_continue; // break out of both loops
            }
        }
        // All non‑wildcard bytes matched
        return const_cast<void*>(static_cast<const void*>(cur - patLen + 1));

outer_continue:
        ;
    }
    return nullptr;
}

/* -------------------------------------------------------------------------- */
/*  Convenience: get module base + size                                      */
/* -------------------------------------------------------------------------- */
static bool GetModuleInfo(const char* moduleName, uintptr_t& outBase, SIZE_T& outSize)
{
    HMODULE hMod = GetModuleHandleA(moduleName);
    if (!hMod)
        return false;

    MODULEINFO mi{};
    if (!GetModuleInformation(GetCurrentProcess(), hMod, &mi, sizeof(mi)))
        return false;

    outBase   = reinterpret_cast<uintptr_t>(mi.lpBaseOfEntryPoint);
    outSize   = mi.SizeOfImage;
    return true;
}

/* -------------------------------------------------------------------------- */
/*  Example usage                                                            */
/* -------------------------------------------------------------------------- */
int main()
{
    /* Example pattern: the first few bytes of MessageBoxA in user32.dll
       (as of Windows 10 1909, may differ across versions).
       Signature:  FF 25 ?? ?? ?? ?? E8 ?? ?? ?? ?? 83 C4 08
       Meaning:    jmp [rip+?]   ; indirect jump
                   call  ?       ; call to MessageBoxExA
                   add  rsp,8    ; clean stack
    */
    const char* patternSig = "FF 25 ?? ?? ?? ?? E8 ?? ?? ?? ?? 83 C4 08";

    try {
        PatternData pat = ParsePattern(patternSig);

        uintptr_t moduleBase = 0;
        SIZE_T    moduleSize = 0;
        if (!GetModuleInfo("user32.dll", moduleBase, moduleSize)) {
            std::cerr << "Failed to get module info for user32.dll\n";
            return 1;
        }

        std::cout << "Scanning user32.dll (0x" << std::hex << moduleBase
                  << " - size 0x" << moduleSize << ")\n";

        void* found = ScanMemory(reinterpret_cast<void*>(moduleBase),
                                 moduleSize,
                                 pat,
                                 true); // use skip table – change to false for pure linear scan

        if (found) {
            std::cout << "Pattern found at address: 0x"
                      << std::hex << reinterpret_cast<uintptr_t>(found) << std::dec << "\n";
        } else {
            std::cout << "Pattern not found.\n";
        }
    } catch (const std::exception& ex) {
        std::cerr << "Error: " << ex.what() << "\n";
        return 1;
    }
    return 0;
}
```

---

## 2.  How the code works (deep dive)

| Section | Purpose | Key Points |
|---------|---------|------------|
| **ParsePattern** | Turns a human‑readable signature (`"48 8B 05 ?? ?? ?? ??"`) into two parallel arrays: `bytes` (the concrete values, `0` for wildcards) and `mask` (`'x'` = must match, `'?'` = ignore). | Tokens are space‑separated. `"??"` → wildcard. Anything else is parsed as a hex byte (`std::stoul(...,16)`). |
| **BuildSkipTable** | Implements the Boyer‑Moore‑Horspool “bad‑character” heuristic, but only for bytes that are **not** wildcards. The table tells us how far we can shift the window when a mismatch occurs at a given position. | For patterns < 4 bytes the overhead outweighs the benefit, so the caller can disable it. |
| **ScanMemory** | Core scanning routine. Two branches: <br>1. **Simple linear scan** – tight inner loop, early‑exit on first mismatch. <br>2. **Horspool‑accelerated scan** – uses the skip table to jump ahead when the last byte of the window mismatches. | The algorithm works on raw pointers; no virtual‑memory protection changes are needed because we only read from the target process’s own address space (typical for a trainer/in‑process scanner). |
| **GetModuleInfo** | Wrapper around `GetModuleHandleA` + `GetModuleInformation` to retrieve the base address and size (`SizeOfImage`) of a module. | Returns `false` if the module cannot be located or the info call fails. |
| **main** | Demonstrates usage: <br>1. Define a signature (example from `MessageBoxA`). <br>2. Parse it. <br>3. Obtain `user32.dll` base/size. <br>4. Call `ScanMemory`. <br>5. Print the result. | The example pattern is deliberately version‑agnostic (uses wildcards for the variable addresses). In practice you may need to adjust the pattern for the target OS/build. |

### Why this is “optimized”

* **Early‑out inner loop** – as soon as a byte fails the mask test we break, avoiding unnecessary comparisons.
* **Skip table (Horspool)** – for patterns ≥ 4 bytes we can jump multiple bytes ahead on a mismatch, reducing the number of inner‑loop iterations from O(N·M) to roughly O(N) in the best case.
* **Cache‑friendly** – we scan linearly, reading contiguous memory; the CPU prefetcher works efficiently.
* **No dynamic allocations inside the hot loop** – the pattern data and skip table are allocated once before scanning.
* **Type‑safe** – uses `uintptr_t` for addresses, `SIZE_T` for sizes, and `std::vector<uint8_t>` for the pattern.

If you need even more speed (e.g., scanning a 2 GB region), you can replace the inner loop with SIMD (`_mm_cmpeq_epi8` on 16‑byte chunks) and handle the mask via a separate equality mask, but the presented version already gives a solid baseline with minimal dependencies.

---

## 3.  Portability notes

* **Windows only** – relies on the Win32 API (`GetModuleHandleA`, `GetModuleInformation`).  
* **64‑bit** – uses `uintptr_t` and `SIZE_T`. The same code compiles for 32‑bit if you change the project target; the algorithm itself is agnostic to pointer size.  
* **Compiler** – any C++17‑compatible compiler works (MSVC, GCC, Clang).  
* **Runtime** – no external libraries; only the Windows SDK and the C++ standard library.

---

### Feel free to adapt

* Change `useSkipTable` to `false` for a pure linear scan (useful for debugging or very short patterns).  
* Replace the example pattern with any signature you need (e.g., from a game, a driver, or a system API).  
* Integrate the `ScanMemory` function into a larger tool that enumerates all modules (`CreateToolhelp32Snapshot` + `Module32First/Next`) if you want a full‑process scanner.  

Happy reverse‑engineering! 🚀

# C++ Manual Map Injector — Complete Implementation

Manual mapping is a core technique in reverse engineering, security research, anti-cheat development, and legitimate software deployment. This guide walks through a complete, production-grade manual mapper with deep explanations of each stage.

---

## Architecture Overview

```
┌─────────────────────────────────────────────────────────────┐
│                    Manual Mapper Flow                       │
├─────────────────────────────────────────────────────────────┤
│  1. Load PE from disk/memory                                │
│  2. Allocate RWX memory in target process                   │
│  3. Write PE headers & sections                             │
│  4. Fix Base Relocations (IMAGE_REL_BASED)                  │
│  5. Resolve Imports via IAT (GetProcAddress + LoadLibrary)  │
│  6. Resolve TLS callbacks (optional)                        │
│  7. Call DllMain(DLL_PROCESS_ATTACH)                        │
│  8. Return module handle                                    │
└─────────────────────────────────────────────────────────────┘
```

---

## 1. Core Data Structures

```cpp
// ManualMap.h
#pragma once

#include <windows.h>
#include <cstdint>
#include <string>
#include <vector>
#include <functional>
#include <fstream>
#include <iostream>

namespace ManualMap {

    // PE Header structures
    struct PEHeaders {
        PIMAGE_DOS_HEADER dosHeader;
        PIMAGE_NT_HEADERS ntHeaders;
        PIMAGE_FILE_HEADER fileHeader;
        PIMAGE_OPTIONAL_HEADER optionalHeader;
        PIMAGE_SECTION_HEADER sections;
        size_t sectionsCount;
    };

    // Relocation block entry
    struct RelocationEntry {
        DWORD virtualAddress;
        WORD type;
    };

    // Import descriptor entry
    struct ImportEntry {
        std::string moduleName;
        std::vector<std::string> functionNames;
        DWORD* iatAddress;  // Import Address Table pointer
    };

    // TLS callback entry
    struct TLSCallback {
        PIMAGE_TLS_CALLBACK callback;
    };

    // Result structure
    struct MapResult {
        bool success;
        std::string errorMessage;
        HMODULE hModule;
        std::vector<RelocationEntry> relocs;
        std::vector<ImportEntry> imports;
        std::vector<TLSCallback> tlsCallbacks;
    };

    // Function pointer types for DllMain
    using DllMainFunc = BOOL(WINAPI*)(HINSTANCE, DWORD, LPVOID);
    using DllMainFuncEx = BOOL(WINAPI*)(HINSTANCE, DWORD, LPVOID, void*);

} // namespace ManualMap
```

