## 2. PE Parsing Engine

```cpp
// PEParser.cpp
#include "ManualMap.h"

namespace ManualMap {

    /**
     * @brief Parse PE headers from a file or memory buffer
     * @param data Raw PE bytes
     * @param size Size of PE data
     * @param headers Output PE header structure
     * @return true if parsing succeeded
     */
    bool ParsePE(const uint8_t* data, size_t size, PEHeaders& headers) {
        if (!data || size < sizeof(IMAGE_DOS_HEADER)) {
            return false;
        }

        headers.dosHeader = reinterpret_cast<PIMAGE_DOS_HEADER>(const_cast<uint8_t*>(data));

        // Validate DOS header magic
        if (headers.dosHeader->e_magic != IMAGE_DOS_SIGNATURE) {
            return false;
        }

        // Validate NT headers
        if (size < headers.dosHeader->e_lfanew + sizeof(DWORD)) {
            return false;
        }

        headers.ntHeaders = reinterpret_cast<PIMAGE_NT_HEADERS>(
            const_cast<uint8_t*>(data) + headers.dosHeader->e_lfanew);

        if (headers.ntHeaders->Signature != IMAGE_NT_SIGNATURE) {
            return false;
        }

        headers.fileHeader = &headers.ntHeaders->FileHeader;
        headers.optionalHeader = &headers.ntHeaders->OptionalHeader;
        headers.sections = IMAGE_FIRST_SECTION(headers.ntHeaders);
        headers.sectionsCount = headers.fileHeader->NumberOfSections;

        // Validate optional header magic
        if (headers.optionalHeader->Magic == IMAGE_NT_OPTIONAL_HDR32_MAGIC) {
            // 32-bit validation
            if (headers.optionalHeader->SizeOfOptionalHeader <
                FIELD_OFFSET(IMAGE_OPTIONAL_HEADER32, DataDirectory)) {
                return false;
            }
        } else if (headers.optionalHeader->Magic == IMAGE_NT_OPTIONAL_HDR64_MAGIC) {
            // 64-bit validation
            if (headers.optionalHeader->SizeOfOptionalHeader <
                FIELD_OFFSET(IMAGE_OPTIONAL_HEADER64, DataDirectory)) {
                return false;
            }
        } else {
            return false;
        }

        return true;
    }

    /**
     * @brief Get section by RVA
     */
    PIMAGE_SECTION_HEADER FindSectionByRVA(const PEHeaders& headers, DWORD rva) {
        for (size_t i = 0; i < headers.sectionsCount; ++i) {
            PIMAGE_SECTION_HEADER section = &headers.sections[i];
            if (rva >= section->VirtualAddress &&
                rva < section->VirtualAddress + section->Misc.VirtualSize) {
                return section;
            }
        }
        return nullptr;
    }

    /**
     * @brief Convert RVA to file offset
     */
    DWORD RVAtoFileOffset(const PEHeaders& headers, DWORD rva) {
        PIMAGE_SECTION_HEADER section = FindSectionByRVA(headers, rva);
        if (!section) {
            return rva; // Not in a section, return as-is
        }
        return rva - section->VirtualAddress + section->PointerToRawData;
    }

} // namespace ManualMap
```

