## 3. Memory Allocation & Writing

```cpp
// MemoryManager.cpp
#include "ManualMap.h"

namespace ManualMap {

    /**
     * @brief Allocate memory in target process
     * @param hProcess Target process handle
     * @param size Size to allocate
     * @param baseAddress Optional base address (NULL for automatic)
     * @return Allocated address or NULL
     */
    LPVOID AllocateInProcess(HANDLE hProcess, SIZE_T size, LPVOID baseAddress = nullptr) {
        MEMORY_BASIC_INFORMATION mbi;
        if (baseAddress) {
            // Try to allocate at preferred base
            LPVOID result = VirtualAllocEx(hProcess, baseAddress, size,
                MEM_COMMIT | MEM_RESERVE, PAGE_READWRITE);
            if (result) return result;
        }

        // Automatic allocation
        return VirtualAllocEx(hProcess, nullptr, size,
            MEM_COMMIT | MEM_RESERVE, PAGE_READWRITE);
    }

    /**
     * @brief Write data to target process memory
     */
    bool WriteToProcess(HANDLE hProcess, LPVOID remoteAddress,
                        const void* localAddress, SIZE_T size) {
        SIZE_T bytesWritten = 0;
        return WriteProcessMemory(hProcess, remoteAddress, localAddress, size, &bytesWritten) &&
               bytesWritten == size;
    }

    /**
     * @brief Map PE sections into target process
     * @param hProcess Target process handle
     * @param headers PE headers
     * @param data Raw PE data
     * @param baseAddress Base address of mapped module
     * @return true if successful
     */
    bool MapSections(HANDLE hProcess, const PEHeaders& headers,
                     const uint8_t* data, LPVOID baseAddress) {
        // Allocate space for all sections
        SIZE_T totalSize = headers.optionalHeader->SizeOfImage;
        LPVOID moduleBase = AllocateInProcess(hProcess, totalSize);
        if (!moduleBase) {
            return false;
        }

        // Write each section
        for (size_t i = 0; i < headers.sectionsCount; ++i) {
            PIMAGE_SECTION_HEADER section = &headers.sections[i];

            // Skip sections with no data
            if (section->SizeOfRawData == 0) {
                continue;
            }

            LPVOID sectionAddress = reinterpret_cast<LPBYTE>(moduleBase) + section->VirtualAddress;
            const uint8_t* sectionData = data + section->PointerToRawData;

            if (!WriteToProcess(hProcess, sectionAddress, sectionData, section->SizeOfRawData)) {
                return false;
            }
        }

        return true;
    }

} // namespace ManualMap
```

