## 4. Base Relocation Fixing

```cpp
// RelocationFixer.cpp
#include "ManualMap.h"

namespace ManualMap {

    /**
     * @brief Apply base relocations to fix absolute addresses
     * @param hProcess Target process handle
     * @param headers PE headers
     * @param baseAddress Actual base address where module was mapped
     * @param originalBase Preferred base address from PE header
     * @return true if successful
     */
    bool FixBaseRelocations(HANDLE hProcess, const PEHeaders& headers,
                            LPVOID baseAddress, DWORD_PTR originalBase) {
        DWORD_PTR delta = reinterpret_cast<DWORD_PTR>(baseAddress) - originalBase;

        if (delta == 0) {
            return true; // No relocation needed
        }

        // Check if relocation directory exists
        PIMAGE_DATA_DIRECTORY relocDir = &headers.optionalHeader->DataDirectory[IMAGE_DIRECTORY_ENTRY_BASERELOC];
        if (relocDir->Size == 0 || relocDir->VirtualAddress == 0) {
            return true; // No relocations needed
        }

        LPVOID relocBase = reinterpret_cast<LPBYTE>(baseAddress) + relocDir->VirtualAddress;
        DWORD relocSize = relocDir->Size;

        LPBYTE current = reinterpret_cast<LPBYTE>(relocBase);
        LPBYTE end = current + relocSize;

        while (current < end) {
            PIMAGE_BASE_RELOCATION block = reinterpret_cast<PIMAGE_BASE_RELOCATION>(current);

            if (block->VirtualAddress == 0 || block->SizeOfBlock == 0) {
                break; // End of relocation table
            }

            if (block->SizeOfBlock < sizeof(IMAGE_BASE_RELOCATION)) {
                return false; // Corrupt block
            }

            // Calculate number of entries in this block
            DWORD entriesCount = (block->SizeOfBlock - sizeof(IMAGE_BASE_RELOCATION)) / sizeof(WORD);
            WORD* entries = reinterpret_cast<WORD*>(current + sizeof(IMAGE_BASE_RELOCATION));

            // Apply each relocation entry
            for (DWORD i = 0; i < entriesCount; ++i) {
                WORD entry = entries[i];
                WORD type = entry >> 12;
                WORD offset = entry & 0x0FFF;

                LPVOID address = reinterpret_cast<LPBYTE>(baseAddress) + block->VirtualAddress + offset;

                switch (type) {
                case IMAGE_REL_BASED_ABSOLUTE:
                    // No relocation needed
                    break;

                case IMAGE_REL_BASED_HIGHLOW:
                {
                    // 32-bit relative address
                    DWORD* value = reinterpret_cast<DWORD*>(address);
                    *value += static_cast<DWORD>(delta);
                    break;
                }

                case IMAGE_REL_BASED_DIR64:
                {
                    // 64-bit relative address
                    DWORD64* value = reinterpret_cast<DWORD64*>(address);
                    *value += delta;
                    break;
                }

                case IMAGE_REL_BASED_HIGH:
                {
                    WORD* value = reinterpret_cast<WORD*>(address);
                    *value = static_cast<WORD>((*value + HIWORD(delta)) & 0xFFFF);
                    break;
                }

                case IMAGE_REL_BASED_LOW:
                {
                    WORD* value = reinterpret_cast<WORD*>(address);
                    *value = static_cast<WORD>((*value + LOWORD(delta)) & 0xFFFF);
                    break;
                }

                default:
                    // Unknown relocation type - log but continue
                    break;
                }
            }

            // Move to next block
            current += block->SizeOfBlock;
        }

        return true;
    }

} // namespace ManualMap
```

