## 5. Import Resolution (IAT)

```cpp
// ImportResolver.cpp
#include "ManualMap.h"

namespace ManualMap {

    /**
     * @brief Resolve a single function import
     * @param hProcess Target process handle
     * @param moduleName Module name (e.g., "kernel32.dll")
     * @param functionName Function name (e.g., "GetProcAddress")
     * @param iatAddress Pointer to IAT entry to fill
     * @return true if resolved
     */
    bool ResolveImport(HANDLE hProcess, const std::string& moduleName,
                       const std::string& functionName, DWORD* iatAddress) {
        // Get module handle
        HMODULE hModule = GetModuleHandleA(moduleName.c_str());
        if (!hModule) {
            // Try loading the module
            hModule = LoadLibraryA(moduleName.c_str());
            if (!hModule) {
                return false;
            }
        }

        // Get function address
        FARPROC functionAddress = GetProcAddress(hModule, functionName.c_str());
        if (!functionAddress) {
            return false;
        }

        // Write to IAT in target process
        SIZE_T bytesWritten = 0;
        return WriteProcessMemory(hProcess, iatAddress, &functionAddress,
            sizeof(FARPROC), &bytesWritten) && bytesWritten == sizeof(FARPROC);
    }

    /**
     * @brief Resolve all imports from Import Directory
     * @param hProcess Target process handle
     * @param headers PE headers
     * @param baseAddress Base address of mapped module
     * @return true if all imports resolved
     */
    bool ResolveImports(HANDLE hProcess, const PEHeaders& headers, LPVOID baseAddress) {
        PIMAGE_DATA_DIRECTORY importDir = &headers.optionalHeader->DataDirectory[IMAGE_DIRECTORY_ENTRY_IMPORT];
        if (importDir->Size == 0 || importDir->VirtualAddress == 0) {
            return true; // No imports to resolve
        }

        PIMAGE_IMPORT_DESCRIPTOR importDesc =
            reinterpret_cast<PIMAGE_IMPORT_DESCRIPTOR>(
                reinterpret_cast<LPBYTE>(baseAddress) + importDir->VirtualAddress);

        while (importDesc->Name != 0) {
            std::string moduleName = reinterpret_cast<char*>(
                reinterpret_cast<LPBYTE>(baseAddress) + importDesc->Name);

            // Get original first thunk (function names)
            PIMAGE_THUNK_DATA originalFirstThunk =
                reinterpret_cast<PIMAGE_THUNK_DATA>(
                    reinterpret_cast<LPBYTE>(baseAddress) + importDesc->OriginalFirstThunk);

            // Get IAT (import address table)
            PIMAGE_THUNK_DATA firstThunk =
                reinterpret_cast<PIMAGE_THUNK_DATA>(
                    reinterpret_cast<LPBYTE>(baseAddress) + importDesc->FirstThunk);

            DWORD* iatAddress = reinterpret_cast<DWORD*>(firstThunk);

            // Resolve each function
            while (originalFirstThunk->u1.AddressOfData != 0) {
                std::string functionName;

                // Check if imported by ordinal or by name
                if (originalFirstThunk->u1.Ordinal & IMAGE_ORDINAL_FLAG) {
                    // Imported by ordinal
                    WORD ordinal = originalFirstThunk->u1.Ordinal & 0xFFFF;
                    functionName = "Ordinal_" + std::to_string(ordinal);
                } else {
                    // Imported by name
                    PIMAGE_IMPORT_BY_NAME importByName =
                        reinterpret_cast<PIMAGE_IMPORT_BY_NAME>(
                            reinterpret_cast<LPBYTE>(baseAddress) +
                            originalFirstThunk->u1.AddressOfData);
                    functionName = importByName->Name;
                }

                // Resolve the import
                if (!ResolveImport(hProcess, moduleName, functionName, iatAddress)) {
                    std::cerr << "Failed to resolve import: " << moduleName << "!" << functionName << std::endl;
                    return false;
                }

                originalFirstThunk++;
                iatAddress++;
                firstThunk++;
            }

            importDesc++;
        }

        return true;
    }

} // namespace ManualMap
```

