## 6. TLS Callback Invocation

```cpp
// TLSHandler.cpp
#include "ManualMap.h"

namespace ManualMap {

    /**
     * @brief Invoke TLS callbacks in target process
     * @param hProcess Target process handle
     * @param headers PE headers
     * @param baseAddress Base address of mapped module
     * @return true if successful
     */
    bool InvokeTLSCallbacks(HANDLE hProcess, const PEHeaders& headers, LPVOID baseAddress) {
        PIMAGE_DATA_DIRECTORY tlsDir = &headers.optionalHeader->DataDirectory[IMAGE_DIRECTORY_ENTRY_TLS];
        if (tlsDir->Size == 0 || tlsDir->VirtualAddress == 0) {
            return true; // No TLS data
        }

        PIMAGE_TLS_DIRECTORY tls =
            reinterpret_cast<PIMAGE_TLS_DIRECTORY>(
                reinterpret_cast<LPBYTE>(baseAddress) + tlsDir->VirtualAddress);

        // Get callback array
        PIMAGE_TLS_CALLBACK* callbacks =
            reinterpret_cast<PIMAGE_TLS_CALLBACK*>(tls->AddressOfCallBacks);

        if (!callbacks) {
            return true; // No callbacks
        }

        // Invoke each callback
        for (DWORD i = 0; callbacks[i] != nullptr; ++i) {
            PIMAGE_TLS_CALLBACK callback = callbacks[i];
            LPVOID callbackAddress = reinterpret_cast<LPVOID>(callback);

            // Call the callback
            BOOL result = callback(baseAddress, DLL_PROCESS_ATTACH, nullptr);
            if (!result) {
                return false;
            }
        }

        return true;
    }

} // namespace ManualMap
