```cpp
// DllMainInvoker.cpp
#include "ManualMap.h"

namespace ManualMap {

    /**
     * @brief Invoke DllMain in target process
     * @param hProcess Target process handle
     * @param baseAddress Base address of mapped module
     * @param reason DLL_PROCESS_ATTACH
     * @return true if successful
     */
    bool InvokeDllMain(HANDLE hProcess, LPVOID baseAddress, DWORD reason = DLL_PROCESS_ATTACH) {
        // Get DllMain address from export directory
        PIMAGE_DATA_DIRECTORY exportDir = &reinterpret_cast<PIMAGE_NT_HEADERS>(
            reinterpret_cast<uint8_t*>(baseAddress) -
            reinterpret_cast<PIMAGE_DOS_HEADER>(baseAddress)->e_lfanew)->OptionalHeader->DataDirectory[IMAGE_DIRECTORY_ENTRY_EXPORT];

        // Actually, we need the PE headers separately
        return false;
    }

    /**
     * @brief Invoke DllMain with proper PE headers
     */
    bool InvokeDllMain(HANDLE hProcess, LPVOID baseAddress, const PEHeaders& headers,
                       DWORD reason = DLL_PROCESS_ATTACH) {
        PIMAGE_DATA_DIRECTORY exportDir = &headers.optionalHeader->DataDirectory[IMAGE_DIRECTORY_ENTRY_EXPORT];
        if (exportDir->Size == 0 || exportDir->VirtualAddress == 0) {
            return true; // No exports, no DllMain
        }

        PIMAGE_EXPORT_DIRECTORY exportDirData =
            reinterpret_cast<PIMAGE_EXPORT_DIRECTORY>(
                reinterpret_cast<LPBYTE>(baseAddress) + exportDir->VirtualAddress);

        // Find DllMain in export table
        DWORD* nameOffsets = reinterpret_cast<DWORD*>(
            reinterpret_cast<LPBYTE>(baseAddress) + exportDirData->AddressOfNames);
        WORD* ordinalOffsets = reinterpret_cast<WORD*>(
            reinterpret_cast<LPBYTE>(baseAddress) + exportDirData->AddressOfNameOrdinals);
        DWORD* functionAddresses = reinterpret_cast<DWORD*>(
            reinterpret_cast<LPBYTE>(baseAddress) + exportDirData->AddressOfFunctions);

        for (DWORD i = 0; i < exportDirData->NumberOfNames; ++i) {
            std::string functionName = reinterpret_cast<char*>(
                reinterpret_cast<LPBYTE>(baseAddress) + nameOffsets[i]);

            if (functionName == "DllMain") {
                DWORD functionRVA = functionAddresses[ordinalOffsets[i]];
                LPVOID dllMainAddress = reinterpret_cast<LPVOID>(
                    reinterpret_cast<LPBYTE>(baseAddress) + functionRVA);

                // Call DllMain
                DllMainFunc dllMain = reinterpret_cast<DllMainFunc>(dllMainAddress);
                BOOL result = dllMain(baseAddress, reason, nullptr);
                return result != FALSE;
            }
        }

        return true; // No DllMain found, that's okay
    }

} // namespace ManualMap
