## 8. Main Injector Function

```cpp
// ManualMapper.cpp
#include "ManualMap.h"

namespace ManualMap {

    /**
     * @brief Complete manual mapping of a PE into a target process
     * @param hProcess Target process handle
     * @param peData Raw PE bytes
     * @param peSize Size of PE data
     * @param baseAddress Optional preferred base address
     * @param callDllMain Whether to call DllMain
     * @return MapResult with details
     */
    MapResult ManualMap(HANDLE hProcess, const uint8_t* peData, size_t peSize,
                        LPVOID baseAddress = nullptr, bool callDllMain = true) {
        MapResult result;
        result.success = false;

        try {
            // Step 1: Parse PE headers
            PEHeaders headers;
            if (!ParsePE(peData, peSize, headers)) {
                result.errorMessage = "Failed to parse PE headers";
                return result;
            }

            // Step 2: Allocate memory and map sections
            LPVOID moduleBase = nullptr;
            if (!MapSections(hProcess, headers, peData, baseAddress)) {
                result.errorMessage = "Failed to allocate memory in target process";
                return result;
            }

            // Get actual base address
            moduleBase = baseAddress;
            if (!moduleBase) {
                // Query the allocated address
                MEMORY_BASIC_INFORMATION mbi;
                if (VirtualQueryEx(hProcess, baseAddress, &mbi, sizeof(mbi))) {
                    moduleBase = mbi.BaseAddress;
                }
            }

            // Step 3: Fix base relocations
            if (!FixBaseRelocations(hProcess, headers, moduleBase,
                headers.optionalHeader->ImageBase)) {
                result.errorMessage = "Failed to fix base relocations";
                return result;
            }

            // Step 4: Resolve imports
            if (!ResolveImports(hProcess, headers, moduleBase)) {
                result.errorMessage = "Failed to resolve imports";
                return result;
            }

            // Step 5: Invoke TLS callbacks
            if (callDllMain && !InvokeTLSCallbacks(hProcess, headers, moduleBase)) {
                result.errorMessage = "TLS callback failed";
                return result;
            }

            // Step 6: Call DllMain
            if (callDllMain && !InvokeDllMain(hProcess, moduleBase, headers)) {
                result.errorMessage = "DllMain failed";
                return result;
            }

            result.success = true;
            result.hModule = reinterpret_cast<HMODULE>(moduleBase);

        } catch (const std::exception& e) {
            result.errorMessage = std::string("Exception: ") + e.what();
        }

        return result;
    }

    /**
     * @brief Load PE from file and manually map it
     */
    MapResult ManualMapFromFile(HANDLE hProcess, const std::string& filePath,
                                LPVOID baseAddress = nullptr, bool callDllMain = true) {
        // Read file into memory
        std::ifstream file(filePath, std::ios::binary);
        if (!file.is_open()) {
            MapResult result;
            result.errorMessage = "Failed to open file: " + filePath;
            return result;
        }

        std::vector<uint8_t> peData((std::istreambuf_iterator<char>(file)),
                                    std::istreambuf_iterator<char>());
        file.close();

        return ManualMap(hProcess, peData.data(), peData.size(), baseAddress, callDllMain);
    }

} // namespace ManualMap
```

