        return 1;
    }

    // Manually map the DLL
    ManualMap::MapResult result = ManualMap::ManualMapFromFile(hProcess, dllPath);

    if (result.success) {
        std::cout << "Manual mapping successful!" << std::endl;
        std::cout << "Module base: " << result.hModule << std::endl;
        std::cout << "Relocations applied: " << result.relocs.size() << std::endl;
        std::cout << "Imports resolved: " << result.imports.size() << std::endl;
    } else {
        std::cerr << "Manual mapping failed: " << result.errorMessage << std::endl;
    }

    CloseHandle(hProcess);
    return result.success ? 0 : 1;
