```cpp
/******************************************************************************************
 *  pattern_scanner.hpp
 *
 *  High‑performance pattern scanner for large memory regions.
 *  Supports AVX2 (primary) and SSE4.2 (fallback) with wildcard '?' handling.
 *
 *  Author:  (you)
 *  License: MIT  – feel free to adapt / embed in your project.
 ******************************************************************************************/

#ifndef PATTERN_SCANNER_HPP
#define PATTERN_SCANNER_HPP

#include <algorithm>
#include <atomic>
#include <cstddef>
#include <cstdint>
#include <exception>
#include <immintrin.h>   // SSE/AVX intrinsics
#include <mutex>
#include <thread>
#include <vector>
#if defined(_WIN32)
#   include <windows.h>
#   include <psapi.h>
#else
#   include <unistd.h>
#   include <sys/types.h>
#   include <sys/ptrace.h>
#   include <sys/wait.h>
#endif

namespace pattern_scanner {

/* -------------------------------------------------------------------------- */
/*  Helper: CPU feature detection (compile‑time constants, runtime check)    */
/* -------------------------------------------------------------------------- */
inline bool has_avx2() {
#if defined(__GNUC__) || defined(__clang__)
    return __builtin_cpu_supports("avx2");
#else
    // MSVC: use __cpuidex
    int info[4] = {};
    __cpuidex(info, 7, 0);
    return (info[1] & bit_AVX2) != 0;
#endif
}
inline bool has_sse42() {
#if defined(__GNUC__) || defined(__clang__)
    return __builtin_cpu_supports("sse4.2");
#else
    int info[4] = {};
    __cpuidex(info, 1, 0);
    return (info[2] & bit_SSE42) != 0;
#endif
}

/* -------------------------------------------------------------------------- */
/*  Pattern representation                                                    */
/* -------------------------------------------------------------------------- */
struct Pattern {
    std::vector<std::uint8_t> bytes;   // pattern bytes (length = pattern size)
    std::vector<std::uint8_t> mask;    // 0xff = exact match, 0x00 = wildcard ('?')

    Pattern() = default;
    Pattern(const std::string& pattern_str) {
        // Expected format: "48 89 5C 24 ? 0F 84 ? ? ? ?"
        // Spaces separate bytes; '?' means wildcard.
        std::size_t pos = 0;
        while (pos < pattern_str.size()) {
            // skip whitespace
            while (pos < pattern_str.size() && std::isspace(pattern_str[pos])) ++pos;
            if (pos >= pattern_str.size()) break;

            if (pattern_str[pos] == '?') {
                bytes.push_back(0);
                mask.push_back(0x00);
                ++pos;
                if (pos < pattern_str.size() && pattern_str[pos] == ' ') ++pos; // consume optional space
                continue;
            }

            // parse hex byte
            if (pos + 2 > pattern_str.size())
                throw std::invalid_argument("Incomplete hex byte in pattern");
            char hex[3] = { pattern_str[pos], pattern_str[pos + 1], 0 };
            unsigned int val;
            if (std::sscanf(hex, "%2x", &val) != 1)
                throw std::invalid_argument("Invalid hex byte in pattern");
            bytes.push_back(static_cast<std::uint8_t>(val));
            mask.push_back(0xff);
            pos += 2;
            if (pos < pattern_str.size() && pattern_str[pos] == ' ') ++pos;
        }
        if (bytes.empty())
            throw std::invalid_argument("Pattern string produced zero-length pattern");
    }

    std::size_t size() const noexcept { return bytes.size(); }
};

/* -------------------------------------------------------------------------- */
/*  Scalar fallback (used for tail < 16 bytes or when SIMD unavailable)      */
/* -------------------------------------------------------------------------- */
inline bool match_scalar(const std::uint8_t* data,
                         const Pattern& pat,
                         std::size_t offset) noexcept {
    for (std::size_t i = 0; i < pat.size(); ++i) {
        if ((pat.mask[i] & data[offset + i]) != (pat.mask[i] & pat.bytes[i]))
            return false;
    }
    return true;
}

/* -------------------------------------------------------------------------- */
/*  SSE4.2 implementation (processes 16 bytes at a time)                     */
/* -------------------------------------------------------------------------- */
inline bool match_sse(const std::uint8_t* data,
                      const Pattern& pat,
                      std::size_t offset) noexcept {
    // Load pattern bytes and mask into registers
    const __m128i pat_bytes = _mm_loadu_si128(reinterpret_cast<const __m128i*>(pat.bytes.data()));
    const __m128i pat_mask  = _mm_loadu_si128(reinterpret_cast<const __m128i*>(pat.mask.data()));

    // Process the pattern in 16‑byte strides
    for (std::size_t i = 0; i + 15 < pat.size(); i += 16) {
        const __m128i chunk = _mm_loadu_si128(reinterpret_cast<const __m128i*>(data + offset + i));
        const __m128i masked_chunk = _mm_and_si128(chunk, pat_mask);
        const __m128i masked_pat   = _mm_and_si128(pat_bytes, pat_mask);
        if (_mm_movemask_epi8(_mm_cmpeq_si128(masked_chunk, masked_pat)) != 0xFFFF)
            return false; // mismatch in this 16‑byte block
    }

    // Handle any remaining tail (<16 bytes) with scalar
    const std::size_t tail_start = (pat.size() / 16) * 16;
    return match_scalar(data, pat, offset + tail_start);
}

/* -------------------------------------------------------------------------- */
/*  AVX2 implementation (processes 32 bytes at a time)                       */
/* -------------------------------------------------------------------------- */
inline bool match_avx2(const std::uint8_t* data,
                       const Pattern& pat,
                       std::size_t offset) noexcept {
    // Load pattern bytes and mask into registers (may need two registers if >32)
    const std::size_t pat_len = pat.size();
    std::size_t i = 0;

    // Main loop: 32‑byte chunks
    for (; i + 31 < pat_len; i += 32) {
        const __m256i pat_bytes = _mm256_loadu_si256(reinterpret_cast<const __m256i*>(pat.bytes.data() + i));
        const __m256i pat_mask  = _mm256_loadu_si256(reinterpret_cast<const __m256i*>(pat.mask.data() + i));

        const __m256i chunk = _mm256_loadu_si256(reinterpret_cast<const __m256i*>(data + offset + i));
        const __m256i masked_chunk = _mm256_and_si256(chunk, pat_mask);
        const __m256i masked_pat   = _mm256_and_si256(pat_bytes, pat_mask);

        if (_mm256_movemask_epi8(_mm256_cmpeq_si256(masked_chunk, masked_pat)) != 0xFFFFFFFF)
            return false;
    }

    // Remainder: could be 0‑31 bytes. Use SSE if >=16, else scalar.
    if (i + 15 < pat_len) {
        // SSE path for the next 16 bytes (if available)
        const __m128i pat_bytes = _mm_loadu_si128(reinterpret_cast<const __m128i*>(pat.bytes.data() + i));
        const __m128i pat_mask  = _mm_loadu_si128(reinterpret_cast<const __m128i*>(pat.mask.data() + i));

        const __m128i chunk = _mm_loadu_si128(reinterpret_cast<const __m128i*>(data + offset + i));
        const __m128i masked_chunk = _mm_and_si128(chunk, pat_mask);
        const __m128i masked_pat   = _mm_and_si128(pat_bytes, pat_mask);

        if (_mm_movemask_epi8(_mm_cmpeq_si128(masked_chunk, masked_pat)) != 0xFFFF)
            return false;
        i += 16;
    }
    // Final tail (<16 bytes) – scalar
    return match_scalar(data, pat, offset + i);
}

/* -------------------------------------------------------------------------- */
/*  Dispatcher – picks the best available implementation at runtime          */
/* -------------------------------------------------------------------------- */
inline bool match(const std::uint8_t* data,
                  const Pattern& pat,
                  std::size_t offset) noexcept {
    if (has_avx2())
        return match_avx2(data, pat, offset);
    if (has_sse42())
        return match_sse(data, pat, offset);
    return match_scalar(data, pat, offset);
}

/* -------------------------------------------------------------------------- */
/*  Thread‑pool worker                                                       */
/* -------------------------------------------------------------------------- */
class Scanner {
public:
    using result_container = std::vector<std::size_t>;

    Scanner(std::size_t chunk_size = 4 * 1024 * 1024)   // 4 MiB default chunk
        : chunk_size_(chunk_size) {}

    /// Scan the memory region [begin, end) for all occurrences of `pat`.
    /// Returns a vector of offsets (relative to `begin`) where the pattern matches.
    result_container scan(const std::uint8_t* begin,
                          const std::uint8_t* end,
                          const Pattern& pat,
                          std::size_t max_threads = std::thread::hardware_concurrency()) {
        if (!begin || !end || end <= begin)
            throw std::invalid_argument("Invalid memory range");
        if (pat.size() == 0)
            throw std::invalid_argument("Empty pattern");

        const std::size_t total_size = static_cast<std::size_t>(end - begin);
        const std::size_t thread_count = std::min<std::size_t>(
            max_threads ? max_threads : std::thread::hardware_concurrency(),
            (total_size + chunk_size_ - 1) / chunk_size_); // at least one thread per chunk

        result_container results;
        results.reserve(total_size / pat.size() + 1); // rough upper bound
        std::mutex results_mtx;
        std::atomic<std::size_t> next_offset{0};

        auto worker = [&]() {
            std::size_t local_offset;
            while ((local_offset = next_offset.fetch_add(chunk_size_, std::memory_order_relaxed)) < total_size) {
                const std::size_t chunk_end = std::min(local_offset + chunk_size_, total_size);
                // The scanner may need to read up to pat.size()-1 bytes beyond the chunk
                // to catch matches that straddle the boundary. We therefore scan a
                // slightly larger window and later discard offsets that belong to the
                // next chunk.
                const std::size_t scan_end = std::min(chunk_end + pat.size() - 1, total_size);

                for (std::size_t off = local_offset; off + pat.size() <= scan_end; ++off) {
                    if (match(begin, pat, off)) {
                        std::lock_guard<std::mutex> lk(results_mtx);
                        // Only keep offsets that belong to this chunk (avoid duplicates)
                        if (off < chunk_end)
                            results.push_back(off);
                    }
                }
            }
        };

        std::vector<std::thread> threads;
        threads.reserve(thread_count);
        for (std::size_t i = 0; i < thread_count; ++i)
            threads.emplace_back(worker);
        for (auto& t : threads)
            t.join();

        // Sort results for deterministic output (optional but useful)
        std::sort(results.begin(), results.end());
        return results;
    }

#if defined(_WIN32)
    /// Convenience wrapper that reads another process' memory into a temporary buffer
    /// and scans it. Caller must have sufficient privileges (e.g. debug rights).
    static result_container scan_process(DWORD pid,
                                         uintptr_t base_address,
                                         std::size_t region_size,
                                         const Pattern& pat,
                                         std::size_t max_threads = std::thread::hardware_concurrency()) {
        HANDLE hProc = OpenProcess(PROCESS_VM_READ | PROCESS_QUERY_INFORMATION, FALSE, pid);
        if (!hProc)
            throw std::system_error(GetLastError(), std::system_category(), "OpenProcess failed");

        std::vector<std::uint8_t> buffer(region_size);
        SIZE_T bytes_read = 0;
        if (!ReadProcessMemory(hProc,
                               reinterpret_cast<LPCVOID>(base_address),
                               buffer.data(),
                               region_size,
                               &bytes_read)) {
            CloseHandle(hProc);
            throw std::system_error(GetLastError(), std::system_category(),
                                    "ReadProcessMemory failed");
        }
        CloseHandle(hProc);

        if (bytes_read != region_size)
            throw std::runtime_error("ReadProcessMemory returned fewer bytes than requested");

        Scanner scanner;
        return scanner.scan(buffer.data(),
                            buffer.data() + bytes_read,
                            pat,
                            max_threads);
    }
#endif

private:
    std::size_t chunk_size_;
};

} // namespace pattern_scanner

#endif // PATTERN_SCANNER_HPP
```

### How to use it

```cpp
