#include <iostream>
#include <vector>

int main() {
    try {
        // Example pattern: "48 89 5C 24 ? 0F 84 ? ? ? ?"
        pattern_scanner::Pattern pat("48 89 5C 24 ? 0F 84 ? ? ? ?");

        // Suppose we have a large buffer (e.g. read from a file or another process)
        const std::size_t file_size = 1024 * 1024 * 1024; // 1 GiB
        std::vector<std::uint8_t> buffer(file_size);
        // ... fill buffer with data ...

        pattern_scanner::Scanner scanner;
        auto matches = scanner.scan(buffer.data(),
                                    buffer.data() + buffer.size(),
                                    pat,
                                    std::thread::hardware_concurrency());

        std::cout << "Found " << matches.size() << " matches:\n";
        for (auto off : matches)
            std::cout << "  0x" << std::hex << off << '\n';
    }
    catch (const std::exception& ex) {
        std::cerr << "Error: " << ex.what() << '\n';
        return 1;
    }
    return 0;
}
