## 3. KMDF Driver – `Driver.c`

> **Build environment**: Windows Driver Kit (WDK) 10 or later, Visual Studio 2022 with the “Driver” workload. Target platform: **KMDF**, **Windows 10, version 1809** or newer (any version that ships WDF).

```c
/*=====================================================================
  Driver.c
  KMDF driver that exposes read/write process memory via DeviceIoControl.
  =====================================================================*/

#include <ntddk.h>
#include <wdf.h>
#include "MemRwIoctl.h"

#define DRIVER_TAG 'wrMe'

/* Forward declarations */
DRIVER_INITIALIZE DriverEntry;
EVT_WDF_DRIVER_UNLOAD MemRwDriverUnload;
EVT_WDF_DEVICE_DEVICE_ADD MemRwEvtDeviceAdd;
EVT_WDF_IO_QUEUE_IO_DEVICE_CONTROL MemRwEvtIoDeviceControl;

/* Helper: check if the caller has SeDebugPrivilege (or is SYSTEM) */
static BOOLEAN
CallerHasDebugPrivilege(void)
{
    /* SeDebugPrivilege is the privilege required to open arbitrary processes */
    return SeSinglePrivilegeCheck(
                SeDebugPrivilege,
                KeGetPreviousMode()) == TRUE;
}

/*--------------------------------------------------------------
  EvtIoDeviceControl – handles the two IOCTLs.
  --------------------------------------------------------------*/
VOID
MemRwEvtIoDeviceControl(
    WDFQUEUE      Queue,
    WDFREQUEST    Request,
    size_t        OutputBufferLength,
    size_t        InputBufferLength,
    size_t        OutputBufferLengthUsed)   // not used
{
    UNREFERENCED_PARAMETER(Queue);
    UNREFERENCED_PARAMETER(OutputBufferLength);
    UNREFERENCED_PARAMETER(OutputBufferLengthUsed);

    NTSTATUS status = STATUS_INVALID_DEVICE_REQUEST;
    size_t   bytesReturned = 0;

    /* Retrieve the IOCTL code */
    ULONG ioctlCode;
    WdfRequestGetParameters(
        Request,
        NULL,               // output length (ignored)
        &InputBufferLength,
        NULL,               // input length (ignored)
        &ioctlCode);

    /* Validate input buffer size – must fit MEM_RW_PARAMS */
    if (InputBufferLength < sizeof(MEM_RW_PARAMS))
    {
        status = STATUS_BUFFER_TOO_SMALL;
        goto Complete;
    }

    /* Only allow callers that have the debug privilege (or run as SYSTEM) */
    if (!CallerHasDebugPrivilege())
    {
        status = STATUS_PRIVILEGE_NOT_HELD;
        goto Complete;
    }

    /* Acquire the input buffer (METHOD_BUFFERED => input == output buffer) */
    PMEM_RW_PARAMS params = NULL;
    WdfRequestRetrieveInputBuffer(
        Request,
        sizeof(MEM_RW_PARAMS),
        (PVOID*)&params,
        NULL);

    if (!params)
    {
        status = STATUS_INVALID_PARAMETER;
        goto Complete;
    }

    /* Basic sanity checks on the parameters */
    if (params->Size == 0 ||
        params->TargetAddress == NULL ||
        params->CallerAddress == NULL)
    {
        status = STATUS_INVALID_PARAMETER;
        goto Complete;
    }

    /* Look up the target process object */
    PEPROCESS targetProcess = NULL;
    status = PsLookupProcessByProcessId(
                (HANDLE)params->TargetProcessId,
                &targetProcess);
    if (!NT_SUCCESS(status))
    {
        goto Complete;
    }

    /* Perform the copy – direction depends on the IOCTL */
    SIZE_T bytesCopied = 0;
    if (ioctlCode == IOCTL_MEM_RW_READ)
    {
        /* Read from target process -> caller's buffer */
        status = MmCopyVirtualMemory(
                    targetProcess,
                    params->TargetAddress,
                    PsGetCurrentProcess(),
                    params->CallerAddress,
                    params->Size,
                    KernelMode,   // caller is in user mode, but we are in kernel
                    &bytesCopied);
    }
    else if (ioctlCode == IOCTL_MEM_RW_WRITE)
    {
        /* Write from caller's buffer -> target process */
        status = MmCopyVirtualMemory(
                    PsGetCurrentProcess(),
                    params->CallerAddress,
                    targetProcess,
                    params->TargetAddress,
                    params->Size,
                    KernelMode,
                    &bytesCopied);
    }
    else
    {
        status = STATUS_INVALID_DEVICE_REQUEST;
    }

    if (NT_SUCCESS(status))
    {
        params->BytesTransferred = bytesCopied;
        bytesReturned = sizeof(MEM_RW_PARAMS);
    }

    /* Dereference the process object we obtained */
    if (targetProcess)
        ObDereferenceObject(targetProcess);

Complete:
    WdfRequestCompleteWithInformation(Request, status, bytesReturned);
}

/*--------------------------------------------------------------
  DeviceAdd – creates the device and the default I/O queue.
  --------------------------------------------------------------*/
NTSTATUS
MemRwEvtDeviceAdd(
    WDFDRIVER   Driver,
    PWDFDEVICE_INIT DeviceInit)
{
    UNREFERENCED_PARAMETER(Driver);

    WDF_OBJECT_ATTRIBUTES deviceAttrs;
    WDF_OBJECT_ATTRIBUTES_INIT(&deviceAttrs);
    deviceAttrs.EvtCleanupCallback = NULL; // optional

    WDFDEVICE device;
    NTSTATUS status = WdfDeviceCreate(&DeviceInit, &deviceAttrs, &device);
    if (!NT_SUCCESS(status))
        return status;

    /* Create a default I/O queue for handling DeviceIoControl */
    WDF_IO_QUEUE_CONFIG queueConfig;
    WDF_IO_QUEUE_CONFIG_INIT_DEFAULT_QUEUE(
        &queueConfig,
        WdfIoQueueDispatchSequential);

    queueConfig.EvtIoDeviceControl = MemRwEvtIoDeviceControl;

    WDFQUEUE queue;
    status = WdfIoQueueCreate(device,
                              &queueConfig,
                              WDF_NO_OBJECT_ATTRIBUTES,
                              &queue);
    if (!NT_SUCCESS(status))
        return status;

    /* Create a symbolic link so user‑mode can open \\.\MemRw */
    UNICODE_STRING dosName;
    RtlInitUnicodeString(&dosName, MEMRW_DOS_DEVICE_NAME);

    status = WdfDeviceCreateSymbolicLink(device, &dosName);
    if (!NT_SUCCESS(status))
        return status;

    return STATUS_SUCCESS;
}

/*--------------------------------------------------------------
  DriverUnload – called when the driver is stopped.
  --------------------------------------------------------------*/
VOID
MemRwDriverUnload(
    WDFDRIVER Driver)
{
    UNREFERENCED_PARAMETER(Driver);
    /* No special cleanup needed – WDF takes care of objects */
}

/*--------------------------------------------------------------
  DriverEntry – entry point.
  --------------------------------------------------------------*/
NTSTATUS
DriverEntry(
    PDRIVER_OBJECT  DriverObject,
    PUNICODE_STRING RegistryPath)
{
    UNREFERENCED_PARAMETER(DriverObject);
    UNREFERENCED_PARAMETER(RegistryPath);

    WDF_DRIVER_CONFIG config;
    WDF_DRIVER_CONFIG_INIT(&config, MemRwEvtDeviceAdd);
    config.EvtDriverUnload = MemRwDriverUnload;

    return WdfDriverCreate(DriverObject,
                           RegistryPath,
                           WDF_NO_OBJECT_ATTRIBUTES,
                           &config,
                           WDF_NO_HANDLE);
}
```

### 3.1 Driver Notes & Safety Checks

| Check | Reason |
|-------|--------|
| `CallerHasDebugPrivilege()` | Guarantees that only a process with `SeDebugPrivilege` (typically running as Administrator or SYSTEM) can issue the IOCTLs. This prevents unprivileged user‑mode code from arbitrarily reading/writing memory. |
| `PsLookupProcessByProcessId` + `ObDereferenceObject` | Safely obtains a reference to the target `EPROCESS` and releases it after use. |
| Buffer size validation (`InputBufferLength < sizeof(MEM_RW_PARAMS)`) | Prevents buffer‑overrun attacks. |
| `MmCopyVirtualMemory` with `KernelMode` as the access mode | The driver runs in kernel mode, so we specify `KernelMode` for the *access mode* argument; the function itself checks that the source and target addresses are valid in the respective processes. |
| Zero‑size transfers are rejected | Avoids degenerate calls that could be abused. |
| Symbolic link created via `WdfDeviceCreateSymbolicLink` | Provides the `\\.\MemRw` name that the client opens. |

