## 4. User‑Mode Client – `MemRwClient.cpp`

> **Build environment**: Visual Studio 2022 (or any MSVC toolset) targeting **x64** (or x86 if you build the driver for that architecture). Link with `Setupapi.lib` (optional) – not required for this simple client.

```cpp
/*=====================================================================
  MemRwClient.cpp
  Simple console client that demonstrates reading and writing another
  process's memory via the KMDF driver.
  =====================================================================*/

#define WIN32_LEAN_AND_MEAN
#include <windows.h>
#include <stdio.h>
#include <tchar.h>
#include "MemRwIoctl.h"

#pragma comment(lib, "Advapi32.lib") // for OpenProcessToken etc. (if needed)

// Helper: enable SeDebugPrivilege for the current process (required to open
// arbitrary processes via the driver). Returns TRUE if successful.
static BOOL EnableDebugPrivilege()
{
    HANDLE hToken = NULL;
    if (!OpenProcessToken(GetCurrentProcess(),
                          TOKEN_ADJUST_PRIVILEGES | TOKEN_QUERY,
                          &hToken))
        return FALSE;

    TOKEN_PRIVILEGES tp = {0};
    tp.PrivilegeCount = 1;
    tp.Privileges[0].Attributes = SE_PRIVILEGE_ENABLED;

    if (!LookupPrivilegeValue(NULL, SE_DEBUG_NAME, &tp.Privileges[0].Luid))
    {
        CloseHandle(hToken);
        return FALSE;
    }

    BOOL ok = AdjustTokenPrivileges(hToken,
                                    FALSE,
                                    &tp,
                                    sizeof(tp),
                                    NULL,
                                    NULL);
    CloseHandle(hToken);
    return ok && GetLastError() == ERROR_SUCCESS;
}

// Simple hex dump utility
static void HexDump(const void* data, SIZE_T size)
{
    const unsigned char* p = (const unsigned char*)data;
    for (SIZE_T i = 0; i < size; ++i)
    {
        if (i % 16 == 0) _tprintf(_T("\n%08I64X: "), i);
        _tprintf(_T("%02X "), p[i]);
        if ((i + 1) % 8 == 0) _tprintf(_T(" "));
    }
    _tprintf(_T("\n"));
}

int _tmain(int argc, TCHAR* argv[])
{
    UNREFERENCED_PARAMETER(argc);
    UNREFERENCED_PARAMETER(argv);

    /* --------------------------------------------------------------
       1. Enable the debug privilege – required for the driver to accept
          our IOCTLs.
       --------------------------------------------------------------*/
    if (!EnableDebugPrivilege())
    {
        _tprintf(_T("Failed to enable SeDebugPrivilege. Run as Administrator.\n"));
        return 1;
    }

    /* --------------------------------------------------------------
       2. Open a handle to the driver.
       --------------------------------------------------------------*/
    HANDLE hDevice = CreateFile(
                        MEMRW_DEVICE_NAME,
                        GENERIC_READ | GENERIC_WRITE,
                        0,
                        nullptr,
                        OPEN_EXISTING,
                        FILE_ATTRIBUTE_NORMAL,
                        nullptr);

    if (hDevice == INVALID_HANDLE_VALUE)
    {
        _tprintf(_T("CreateFile failed, error %lu\n"), GetLastError());
        return 1;
    }
    _tprintf(_T("Opened device %s successfully.\n"), MEMRW_DEVICE_NAME);

    /* --------------------------------------------------------------
       3. Example: read 64 bytes from notepad.exe (you can change the PID).
       --------------------------------------------------------------*/
    DWORD targetPid = 0;
    _tprintf(_T("Enter the PID of the target process: "));
    _tscanf(_T("%lu"), &targetPid);

    if (targetPid == 0)
    {
        _tprintf(_T("Invalid PID.\n"));
        CloseHandle(hDevice);
        return 1;
    }

    /* Allocate a buffer in our own process to hold the data we read */
    const SIZE_T readSize = 64;
    BYTE* localBuf = (BYTE*)VirtualAlloc(nullptr,
                                         readSize,
                                         MEM_COMMIT | MEM_RESERVE,
                                         PAGE_READWRITE);
    if (!localBuf)
    {
        _tprintf(_T("VirtualAlloc failed.\n"));
        CloseHandle(hDevice);
        return 1;
    }

    /* Prepare the IOCTL input/output buffer */
    MEM_RW_PARAMS params = {0};
    params.TargetProcessId = (HANDLE)(ULONG_PTR)targetPid;
    params.TargetAddress   = (PVOID)0x0000000000400000; // example: notepad's image base
    params.CallerAddress   = localBuf;
    params.Size            = readSize;

    DWORD bytesReturned = 0;
    BOOL ok = DeviceIoControl(
                hDevice,
                IOCTL_MEM_RW_READ,
                &params,
                sizeof(params),
                &params,
                sizeof(params),
                &bytesReturned,
                nullptr);

    if (!ok)
    {
        _tprintf(_T("DeviceIoControl (READ) failed, error %lu\n"), GetLastError());
    }
    else
    {
        _tprintf(_T("Read %I64u bytes from PID %lu at address %p\n"),
                 params.BytesTransferred, targetPid, params.TargetAddress);
        HexDump(localBuf, params.BytesTransferred);
    }

    /* --------------------------------------------------------------
       4. Example: write a pattern to the same location (demonstrates
          write capability).  Use with extreme caution!
       --------------------------------------------------------------*/
    const SIZE_T writeSize = 16;
    BYTE pattern[writeSize] = {0xAA, 0xBB, 0xCC, 0xDD, 0xEE, 0xFF, 0x00, 0x11,
                               0x22, 0x33, 0x44, 0x55, 0x66, 0x77, 0x88, 0x99};

    params.TargetAddress   = (PVOID)0x0000000000400000; // same address as before
    params.CallerAddress   = pattern;
    params.Size            = writeSize;

    ok = DeviceIoControl(
            hDevice,
            IOCTL_MEM_RW_WRITE,
            &params,
            sizeof(params),
            &params,
            sizeof(params),
            &bytesReturned,
            nullptr);

    if (!ok)
    {
        _tprintf(_T("DeviceIoControl (WRITE) failed, error %lu\n"), GetLastError());
    }
    else
    {
        _tprintf(_T("Wrote %I64u bytes to PID %lu at address %p\n"),
                 params.BytesTransferred, targetPid, params.TargetAddress);
    }

    /* Cleanup */
    VirtualFree(localBuf, 0, MEM_RELEASE);
    CloseHandle(hDevice);
    return 0;
}
```

### 4.1 Client Notes

* The client **must** be run with a token that has `SeDebugPrivilege` (normally “Run as Administrator”). The helper `EnableDebugPrivilege()` attempts to enable it; if it fails, the driver will reject the IOCTLs with `STATUS_PRIVILEGE_NOT_HELD`.
* The example uses a hard‑coded address (`0x0000000000400000`) – the **image base** of many 64‑bit executables. In a real scenario you would obtain the address via other means (e.g., `EnumProcessModules`, `ReadProcessMemory` in a helper tool, or symbols). The client is deliberately simple to illustrate the mechanism.
* **Never** use the write capability on a process you do not own or have explicit permission to modify. Doing so can crash the target process, corrupt data, or violate security policies.

