    [[nodiscard]] constexpr Vec3 floor() const noexcept { return {std::floor(x), std::floor(y), std::floor(z)}; }
    [[nodiscard]] constexpr Vec3 ceil() const noexcept { return {std::ceil(x), std::ceil(y), std::ceil(z)}; }
    [[nodiscard]] constexpr Vec3 fract() const noexcept { return {x - std::floor(x), y - std::floor(y), z - std::floor(z)}; }

    // Lerp / Slerp / Nlerp
    [[nodiscard]] Vec3 lerp(const Vec3& o, float t) const noexcept { return *this + (o - *this) * clamp(t, 0.0f, 1.0f); }
    [[nodiscard]] Vec3 nlerp(const Vec3& o, float t) const noexcept { return lerp(o, t).normalized(); }
    [[nodiscard]] Vec3 slerp(const Vec3& o, float t) const noexcept {
        float dot_val = clamp(dot(o), -1.0f, 1.0f);
        float theta = std::acos(dot_val) * t;
        Vec3 relative = (o - *this * dot_val).normalized();
        return *this * std::cos(theta) + relative * std::sin(theta);
    }

    // Orthonormal basis from this vector (as forward)
    [[nodiscard]] std::pair<Vec3, Vec3> orthonormal_basis() const noexcept {
        Vec3 f = normalized();
        Vec3 up = std::abs(f.y) < 0.99f ? Vec3{0,1,0} : Vec3{1,0,0};
        Vec3 r = f.cross(up).normalized();
        Vec3 u = r.cross(f);
        return {r, u};
    }
};

// Vec3 non-member operators
inline constexpr Vec3 operator+(Vec3 a, const Vec3& b) noexcept { return a += b; }
inline constexpr Vec3 operator-(Vec3 a, const Vec3& b) noexcept { return a -= b; }
inline constexpr Vec3 operator*(Vec3 a, float s) noexcept { return a *= s; }
inline constexpr Vec3 operator*(float s, Vec3 a) noexcept { return a *= s; }
inline constexpr Vec3 operator/(Vec3 a, float s) noexcept { return a /= s; }
inline constexpr float dot(const Vec3& a, const Vec3& b) noexcept { return a.dot(b); }
inline constexpr Vec3 cross(const Vec3& a, const Vec3& b) noexcept { return a.cross(b); }
inline constexpr Vec3 min(const Vec3& a, const Vec3& b) noexcept { return a.min(b); }
inline constexpr Vec3 max(const Vec3& a, const Vec3& b) noexcept { return a.max(b); }
inline constexpr Vec3 clamp(const Vec3& v, const Vec3& lo, const Vec3& hi) noexcept { return max(lo, min(v, hi)); }

