## Usage Examples

```cpp
#include "Math3D.hpp"
#include <iostream>

using namespace math3d;

int main() {
    // Camera setup
    Camera cam;
    cam.position = {0, 2, 5};
    cam.rotation = Quat::from_euler(0.0f, 0.0f, 0.0f); // Looking down -Z
    cam.fov_y = 60.0f * DEG2RAD;
    cam.aspect = 1920.0f / 1080.0f;

    Viewport vp{0, 0, 1920, 1080};

    // World point
    Vec3 world_pos{10, 1, -20};

    // World to screen
    Vec2 screen_pos;
    if (cam.world_to_screen(world_pos, screen_pos, vp)) {
        std::cout << "World " << world_pos << " -> Screen " << screen_pos << "\n";
    }

    // Angle calculation from direction
    Vec3 target_dir = (world_pos - cam.position).normalized();
    Angles angles = Angles::from_forward(target_dir);
    std::cout << "Required angles: " << angles << "\n";

    // Smooth rotation toward target (frame-rate independent)
    Angles current_angles{0, 0, 0};
    float dt = 1.0f / 60.0f;
    float half_life = 0.15f; // 150ms half-life

    for (int i = 0; i < 60; ++i) {
        current_angles.pitch = interpolation::exp_decay(current_angles.pitch, angles.pitch, half_life, dt);
        current_angles.yaw   = interpolation::exp_decay(current_angles.yaw,   angles.yaw,   half_life, dt);
    }
    std::cout << "Smoothed angles: " << current_angles << "\n";

    // Spring-damper for smoother feel
    interpolation::SpringDamper<float> spring_yaw;
    spring_yaw.frequency = 8.0f;
    spring_yaw.damping = 1.0f;
    for (int i = 0; i < 60; ++i) {
        spring_yaw.update(angles.yaw, dt);
    }
    std::cout << "Spring yaw: " << spring_yaw.position * RAD2DEG << "°\n";

    return 0;
}
