## src/hook/minhook_wrapper.hpp

```cpp
#pragma once

#include <MinHook.h>
#include <functional>
#include <string>
#include <unordered_map>
#include <mutex>
#include <stdexcept>
#include <format>

namespace dx_hook {

class MinHookError : public std::runtime_error {
public:
    explicit MinHookError(MH_STATUS status, const std::string& context)
        : std::runtime_error(std::format("MinHook error in {}: {} (0x{:X})", 
            context, MH_StatusToString(status), static_cast<int>(status))),
          status_(status) {}

    MH_STATUS status() const noexcept { return status_; }
private:
    MH_STATUS status_;
};

class ScopedMinHook {
public:
    ScopedMinHook() {
        MH_STATUS status = MH_Initialize();
        if (status != MH_OK && status != MH_ERROR_ALREADY_INITIALIZED) {
            throw MinHookError(status, "MH_Initialize");
        }
        initialized_ = true;
    }

    ~ScopedMinHook() {
        if (initialized_) {
            MH_Uninitialize();
        }
    }

    ScopedMinHook(const ScopedMinHook&) = delete;
    ScopedMinHook& operator=(const ScopedMinHook&) = delete;

    ScopedMinHook(ScopedMinHook&& other) noexcept : initialized_(other.initialized_) {
        other.initialized_ = false;
    }

    ScopedMinHook& operator=(ScopedMinHook&& other) noexcept {
        if (this != &other) {
            if (initialized_) MH_Uninitialize();
            initialized_ = other.initialized_;
            other.initialized_ = false;
        }
        return *this;
    }

private:
    bool initialized_ = false;
};

class HookEntry {
public:
    HookEntry() = default;
    HookEntry(void* target, void* detour, void** original)
        : target_(target), detour_(detour), original_(original) {}

    void enable() {
        if (!enabled_) {
            MH_STATUS status = MH_EnableHook(target_);
            if (status != MH_OK) throw MinHookError(status, "MH_EnableHook");
            enabled_ = true;
        }
    }

    void disable() {
        if (enabled_) {
            MH_STATUS status = MH_DisableHook(target_);
            if (status != MH_OK) throw MinHookError(status, "MH_DisableHook");
            enabled_ = false;
        }
    }

    ~HookEntry() {
        if (enabled_) {
            MH_DisableHook(target_);
        }
        if (target_) {
            MH_RemoveHook(target_);
        }
    }

    void* target() const { return target_; }
    void* detour() const { return detour_; }
    void** original() const { return original_; }

private:
    void* target_ = nullptr;
    void* detour_ = nullptr;
    void** original_ = nullptr;
    bool enabled_ = false;
};

class HookManager {
public:
    static HookManager& instance() {
        static HookManager inst;
        return inst;
    }

    template<typename T>
    bool create_hook(void* target, T detour, T* original, const std::string& name) {
        std::lock_guard lock(mutex_);

        if (hooks_.contains(name)) {
            return false;
        }

        void* original_ptr = nullptr;
        MH_STATUS status = MH_CreateHook(target, reinterpret_cast<void*>(detour), &original_ptr);
        if (status != MH_OK) {
            throw MinHookError(status, std::format("MH_CreateHook for {}", name));
        }

        *original = reinterpret_cast<T>(original_ptr);
        hooks_.emplace(name, HookEntry(target, reinterpret_cast<void*>(detour), &original_ptr));
        return true;
    }

    void enable_all() {
        std::lock_guard lock(mutex_);
        for (auto& [name, hook] : hooks_) {
            hook.enable();
        }
    }

    void disable_all() {
        std::lock_guard lock(mutex_);
        for (auto& [name, hook] : hooks_) {
            hook.disable();
        }
    }

    void enable(const std::string& name) {
        std::lock_guard lock(mutex_);
        if (auto it = hooks_.find(name); it != hooks_.end()) {
            it->second.enable();
        }
    }

    void disable(const std::string& name) {
        std::lock_guard lock(mutex_);
        if (auto it = hooks_.find(name); it != hooks_.end()) {
            it->second.disable();
        }
    }

    void remove(const std::string& name) {
        std::lock_guard lock(mutex_);
        hooks_.erase(name);
    }

    void clear() {
        std::lock_guard lock(mutex_);
        hooks_.clear();
    }

    bool is_enabled(const std::string& name) const {
        std::lock_guard lock(mutex_);
        auto it = hooks_.find(name);
        return it != hooks_.end();
    }

private:
    HookManager() = default;
    std::unordered_map<std::string, HookEntry> hooks_;
    mutable std::mutex mutex_;
};

} // namespace dx_hook
```

