    static HRESULT STDMETHODCALLTYPE dx11_present_hook(IDXGISwapChain* pSwapChain, UINT SyncInterval, UINT Flags);
    static HRESULT STDMETHODCALLTYPE dx11_resize_buffers_hook(IDXGISwapChain* pSwapChain, UINT BufferCount, UINT Width, UINT Height, DXGI_FORMAT NewFormat, UINT SwapChainFlags);

    // DX12 hook callbacks
    static HRESULT STDMETHODCALLTYPE dx12_present_hook(IDXGISwapChain* pSwapChain, UINT SyncInterval, UINT Flags);
    static HRESULT STDMETHODCALLTYPE dx12_resize_buffers_hook(IDXGISwapChain* pSwapChain, UINT BufferCount, UINT Width, UINT Height, DXGI_FORMAT NewFormat, UINT SwapChainFlags);

    // Original function pointers
    using PresentFn = HRESULT(STDMETHODCALLTYPE*)(IDXGISwapChain*, UINT, UINT);
    using ResizeBuffersFn = HRESULT(STDMETHODCALLTYPE*)(IDXGISwapChain*, UINT, UINT, UINT, DXGI_FORMAT, UINT);

    PresentFn dx11_present_original_ = nullptr;
    ResizeBuffersFn dx11_resize_buffers_original_ = nullptr;
    PresentFn dx12_present_original_ = nullptr;
    ResizeBuffersFn dx12_resize_buffers_original_ = nullptr;

    // State
    std::atomic<bool> initialized_{false};
    std::atomic<bool> dx11_active_{false};
    std::atomic<bool> dx12_active_{false};
    std::atomic<bool> imgui_initialized_{false};
    std::atomic<bool> resize_pending_{false};
