namespace dx_hook {

using Microsoft::WRL::ComPtr;

// Static trampolines
HRESULT STDMETHODCALLTYPE HookManager::dx11_present_hook(IDXGISwapChain* pSwapChain, UINT SyncInterval, UINT Flags) {
    auto& manager = HookManager::instance();

    // Initialize on first present
    if (!manager.dx11_active_.load()) {
        std::lock_guard lock(manager.state_mutex_);
        if (!manager.dx11_active_.load()) {
            ComPtr<ID3D11Device> device;
            HRESULT hr = pSwapChain->GetDevice(__uuidof(ID3D11Device), reinterpret_cast<void**>(device.GetAddressOf()));
            if (SUCCEEDED(hr)) {
                device->GetImmediateContext(manager.d3d11_context_.GetAddressOf());
                manager.d3d11_device_ = device;
                manager.swapchain_ = pSwapChain;
                pSwapChain->QueryInterface(__uuidof(IDXGISwapChain3), reinterpret_cast<void**>(manager.swapchain3_.GetAddressOf()));

                DXGI_SWAP_CHAIN_DESC desc;
                pSwapChain->GetDesc(&desc);
                manager.current_width_ = desc.BufferDesc.Width;
                manager.current_height_ = desc.BufferDesc.Height;
                manager.backbuffer_format_ = desc.BufferDesc.Format;

                if (manager.config_.auto_init_imgui) {
                    manager.create_imgui_resources();
                }

                if (manager.config_.on_swapchain_created) {
                    manager.config_.on_swapchain_created(pSwapChain);
                }

                manager.dx11_active_.store(true);
            }
        }
    }

    // Handle resize
    if (manager.resize_pending_.load()) {
        manager.on_resize(manager.current_width_, manager.current_height_);
        manager.resize_pending_.store(false);
    }

    // ImGui frame
    if (manager.imgui_initialized_.load() && manager.config_.on_imgui_render) {
        ImGuiImpl::new_frame_dx11();
        manager.config_.on_imgui_render();
        ImGuiImpl::render_dx11(manager.d3d11_context_.Get());
    }

    return manager.dx11_present_original_(pSwapChain, SyncInterval, Flags);
}

HRESULT STDMETHODCALLTYPE HookManager::dx11_resize_buffers_hook(IDXGISwapChain* pSwapChain, UINT BufferCount, UINT Width, UINT Height, DXGI_FORMAT NewFormat, UINT SwapChainFlags) {
    auto& manager = HookManager::instance();

    // Cleanup ImGui resources before resize
    if (manager.imgui_initialized_.load()) {
        manager.destroy_imgui_resources();
    }

    HRESULT hr = manager.dx11_resize_buffers_original_(pSwapChain, BufferCount, Width, Height, NewFormat, SwapChainFlags);

    if (SUCCEEDED(hr)) {
        DXGI_SWAP_CHAIN_DESC desc;
        pSwapChain->GetDesc(&desc);
        manager.current_width_ = desc.BufferDesc.Width;
        manager.current_height_ = desc.BufferDesc.Height;
        manager.backbuffer_format_ = desc.BufferDesc.Format;
        manager.resize_pending_.store(true);

        if (manager.config_.auto_init_imgui) {
            manager.create_imgui_resources();
        }
    }

    return hr;
}

bool HookManager::init_dx11_hooks() {
    // Find IDXGISwapChain::Present and ResizeBuffers via vtable
    ComPtr<ID3D11Device> temp_device;
    ComPtr<IDXGISwapChain> temp_swapchain;

    DXGI_SWAP_CHAIN_DESC desc = {};
    desc.BufferCount = 1;
    desc.BufferDesc.Width = 100;
    desc.BufferDesc.Height = 100;
    desc.BufferDesc.Format = DXGI_FORMAT_R8G8B8A8_UNORM;
    desc.BufferUsage = DXGI_USAGE_RENDER_TARGET_OUTPUT;
    desc.OutputWindow = GetDesktopWindow();
    desc.SampleDesc.Count = 1;
    desc.Windowed = TRUE;
    desc.SwapEffect = DXGI_SWAP_EFFECT_DISCARD;

    D3D_FEATURE_LEVEL feature_levels[] = { D3D_FEATURE_LEVEL_11_0 };
    D3D_FEATURE_LEVEL obtained_level;

    HRESULT hr = D3D11CreateDeviceAndSwapChain(
        nullptr, D3D_DRIVER_TYPE_HARDWARE, nullptr, 0,
        feature_levels, 1, D3D11_SDK_VERSION,
        &desc, temp_swapchain.GetAddressOf(),
        temp_device.GetAddressOf(), &obtained_level, nullptr
    );

    if (FAILED(hr)) return false;

    // Get vtable
    void** vtable = *reinterpret_cast<void***>(temp_swapchain.Get());

    // Present is at index 8, ResizeBuffers at index 13
    void* present_fn = vtable[8];
    void* resize_buffers_fn = vtable[13];

    temp_swapchain.Reset();
    temp_device.Reset();

    // Create hooks
    try {
        HookManager::instance().create_hook(present_fn, 
            reinterpret_cast<void*>(dx11_present_hook),
            reinterpret_cast<void**>(&dx11_present_original_),
            "DX11_Present");

        HookManager::instance().create_hook(resize_buffers_fn,
            reinterpret_cast<void*>(dx11_resize_buffers_hook),
            reinterpret_cast<void**>(&dx11_resize_buffers_original_),
            "DX11_ResizeBuffers");

        return true;
    } catch (const MinHookError&) {
        return false;
    }
}

void HookManager::cleanup_dx11() {
    if (dx11_active_.load()) {
        destroy_imgui_resources();
        d3d11_context_.Reset();
        d3d11_device_.Reset();
        swapchain3_.Reset();
        swapchain_.Reset();
        dx11_active_.store(false);
    }
}

} // namespace dx_hook
