bool HookManager::init_dx12_hooks() {
    // For DX12, we need to hook IDXGISwapChain3/4 Present/ResizeBuffers
    // The vtable layout is the same as DX11 for these methods

    ComPtr<IDXGIFactory4> factory;
    HRESULT hr = CreateDXGIFactory2(0, IID_PPV_ARGS(&factory));
    if (FAILED(hr)) return false;

    ComPtr<IDXGISwapChain1> swapchain1;
    DXGI_SWAP_CHAIN_DESC1 desc = {};
    desc.Width = 100;
    desc.Height = 100;
    desc.Format = DXGI_FORMAT_R8G8B8A8_UNORM;
    desc.Stereo = FALSE;
    desc.SampleDesc.Count = 1;
    desc.BufferUsage = DXGI_USAGE_RENDER_TARGET_OUTPUT;
    desc.BufferCount = 2;
    desc.SwapEffect = DXGI_SWAP_EFFECT_FLIP_DISCARD;
    desc.Flags = 0;

    hr = factory->CreateSwapChainForHwnd(
        nullptr, GetDesktopWindow(), &desc, nullptr, nullptr, &swapchain1
    );

    if (FAILED(hr)) return false;

    ComPtr<IDXGISwapChain3> swapchain3;
    hr = swapchain1->QueryInterface(IID_PPV_ARGS(&swapchain3));
    if (FAILED(hr)) return false;

    void** vtable = *reinterpret_cast<void***>(swapchain3.Get());

    // Present: index 8, ResizeBuffers: index 13 (same as DX11)
    void* present_fn = vtable[8];
    void* resize_buffers_fn = vtable[13];

    swapchain3.Reset();
    swapchain1.Reset();
    factory.Reset();

    try {
        HookManager::instance().create_hook(present_fn,
            reinterpret_cast<void*>(dx12_present_hook),
            reinterpret_cast<void**>(&dx12_present_original_),
            "DX12_Present");

        HookManager::instance().create_hook(resize_buffers_fn,
            reinterpret_cast<void*>(dx12_resize_buffers_hook),
            reinterpret_cast<void**>(&dx12_resize_buffers_original_),
            "DX12_ResizeBuffers");

        return true;
    } catch (const MinHookError&) {
        return false;
    }
}

void HookManager::cleanup_dx12() {
    if (dx12_active_.load()) {
        destroy_imgui_resources();
        d3d12_device_.Reset();
        swapchain3_.Reset();
        swapchain_.Reset();
        dx12_active_.store(false);
    }
}

} // namespace dx_hook
