namespace dx_hook::utils {

std::vector<WindowInfo> WindowUtils::enumerate_windows(DWORD target_pid) {
    std::vector<WindowInfo> windows;

    EnumWindows([](HWND hwnd, LPARAM lparam) -> BOOL {
        auto& vec = *reinterpret_cast<std::vector<WindowInfo>*>(lparam);
        DWORD pid = 0;
        GetWindowThreadProcessId(hwnd, &pid);

        if (target_pid != 0 && pid != target_pid) return TRUE;
        if (!IsWindowVisible(hwnd)) return TRUE;

        WindowInfo info = get_window_info(hwnd);
        if (info.rect.right - info.rect.left > 0 && info.rect.bottom - info.rect.top > 0) {
            vec.push_back(std::move(info));
        }
        return TRUE;
    }, reinterpret_cast<LPARAM>(&windows));

    return windows;
}

WindowInfo WindowUtils::get_window_info(HWND hwnd) {
    WindowInfo info;
    info.hwnd = hwnd;
    info.title = get_window_title(hwnd);
    info.class_name = get_window_class_name(hwnd);
    info.rect = get_window_rect(hwnd);
    info.process_id = get_window_process_id(hwnd);
    info.thread_id = get_window_thread_id(hwnd);
    info.is_fullscreen = is_window_fullscreen_borderless(hwnd);
    info.is_borderless = (GetWindowLongPtr(hwnd, GWL_STYLE) & WS_CAPTION) == 0;
    return info;
}

HWND WindowUtils::find_game_window(const std::wstring& window_title, const std::wstring& class_name) {
    return FindWindowW(class_name.empty() ? nullptr : class_name.c_str(), window_title.c_str());
}

HWND WindowUtils::find_game_window_by_pid(DWORD pid) {
    HWND result = nullptr;
    EnumWindows([](HWND hwnd, LPARAM lparam) -> BOOL {
        DWORD window_pid = 0;
        GetWindowThreadProcessId(hwnd, &window_pid);
        if (window_pid == (DWORD)lparam && IsWindowVisible(hwnd)) {
            *reinterpret_cast<HWND*>(lparam) = hwnd;
            return FALSE;
        }
        return TRUE;
    }, reinterpret_cast<LPARAM>(&result));
    return result;
}

bool WindowUtils::is_window_fullscreen_borderless(HWND hwnd) {
    RECT window_rect = get_window_rect(hwnd);
    MONITORINFO monitor_info = get_monitor_info(hwnd);

    // Check if window covers entire monitor
    bool covers_monitor = (window_rect.left <= monitor_info.rcMonitor.left &&
                          window_rect.top <= monitor_info.rcMonitor.top &&
                          window_rect.right >= monitor_info.rcMonitor.right &&
                          window_rect.bottom >= monitor_info.rcMonitor.bottom);

    // Check if borderless
    LONG_PTR style = GetWindowLongPtr(hwnd, GWL_STYLE);
    bool borderless = (style & WS_CAPTION) == 0 && (style & WS_THICKFRAME) == 0;

    return covers_monitor && borderless;
}

bool WindowUtils::is_window_maximized(HWND hwnd) {
    WINDOWPLACEMENT placement = { sizeof(WINDOWPLACEMENT) };
    GetWindowPlacement(hwnd, &placement);
    return placement.showCmd == SW_MAXIMIZE;
}

RECT WindowUtils::get_client_rect(HWND hwnd) {
    RECT rect = {};
    GetClientRect(hwnd, &rect);
    return rect;
}

RECT WindowUtils::get_window_rect(HWND hwnd) {
    RECT rect = {};
    GetWindowRect(hwnd, &rect);
    return rect;
}

MONITORINFO WindowUtils::get_monitor_info(HWND hwnd) {
    MONITORINFO info = { sizeof(MONITORINFO) };
    HMONITOR monitor = MonitorFromWindow(hwnd, MONITOR_DEFAULTTONEAREST);
    GetMonitorInfo(monitor, &info);
    return info;
}

bool WindowUtils::set_window_fullscreen_borderless(HWND hwnd, bool enable) {
    if (enable) {
        MONITORINFO monitor_info = get_monitor_info(hwnd);
        LONG_PTR style = GetWindowLongPtr(hwnd, GWL_STYLE);
        style &= ~(WS_CAPTION | WS_THICKFRAME | WS_MINIMIZEBOX | WS_MAXIMIZEBOX | WS_SYSMENU);
        SetWindowLongPtr(hwnd, GWL_STYLE, style);

        SetWindowPos(hwnd, HWND_TOP,
            monitor_info.rcMonitor.left,
            monitor_info.rcMonitor.top,
            monitor_info.rcMonitor.right - monitor_info.rcMonitor.left,
            monitor_info.rcMonitor.bottom - monitor_info.rcMonitor.top,
            SWP_FRAMECHANGED | SWP_NOACTIVATE);
    } else {
        LONG_PTR style = GetWindowLongPtr(hwnd, GWL_STYLE);
        style |= WS_OVERLAPPEDWINDOW;
        SetWindowLongPtr(hwnd, GWL_STYLE, style);
        SetWindowPos(hwnd, HWND_TOP, 100, 100, 1280, 720, SWP_FRAMECHANGED | SWP_NOACTIVATE);
    }
    return true;
}

bool WindowUtils::set_window_pos(HWND hwnd, int x, int y, int width, int height, UINT flags) {
    return SetWindowPos(hwnd, nullptr, x, y, width, height, flags) != FALSE;
}

std::wstring WindowUtils::get_window_title(HWND hwnd) {
    int length = GetWindowTextLengthW(hwnd);
    if (length == 0) return L"";
    std::wstring title(length + 1, L'\0');
    GetWindowTextW(hwnd, &title[0], length + 1);
    title.resize(length);
    return title;
}

std::wstring WindowUtils::get_window_class_name(HWND hwnd) {
    std::wstring class_name(256, L'\0');
    int length = GetClassNameW(hwnd, &class_name[0], 256);
    class_name.resize(length);
    return class_name;
}

DWORD WindowUtils::get_window_process_id(HWND hwnd) {
    DWORD pid = 0;
    GetWindowThreadProcessId(hwnd, &pid);
    return pid;
}

DWORD WindowUtils::get_window_thread_id(HWND hwnd) {
    return GetWindowThreadProcessId(hwnd, nullptr);
}

bool WindowUtils::register_window_class(const std::wstring& class_name, WNDPROC wnd_proc) {
    WNDCLASSEXW wc = {};
    wc.cbSize = sizeof(WNDCLASSEXW);
    wc.style = CS_HREDRAW | CS_VREDRAW;
    wc.lpfnWndProc = wnd_proc;
    wc.hInstance = GetModuleHandle(nullptr);
    wc.hCursor = LoadCursor(nullptr, IDC_ARROW);
    wc.hbrBackground = (HBRUSH)(COLOR_WINDOW + 1);
    wc.lpszClassName = class_name.c_str();
    return RegisterClassExW(&wc) != 0;
}

HWND WindowUtils::create_overlay_window(HWND target_window, const std::wstring& class_name) {
    RECT rect = get_client_rect(target_window);
    int width = rect.right - rect.left;
    int height = rect.bottom - rect.top;

    HWND overlay = CreateWindowExW(
        WS_EX_LAYERED | WS_EX_TRANSPARENT | WS_EX_NOACTIVATE | WS_EX_TOPMOST,
        class_name.c_str(),
        L"ImGui Overlay",
        WS_POPUP,
        0, 0, width, height,
        target_window, nullptr, GetModuleHandle(nullptr), nullptr
    );

    if (overlay) {
        SetLayeredWindowAttributes(overlay, 0, 255, LWA_ALPHA);
        ShowWindow(overlay, SW_SHOW);
    }

    return overlay;
}

void WindowUtils::destroy_overlay_window(HWND hwnd) {
    if (hwnd) DestroyWindow(hwnd);
}

void WindowUtils::enable_high_dpi_awareness() {
    SetProcessDpiAwarenessContext(DPI_AWARENESS_CONTEXT_PER_MONITOR_AWARE_V2);
}

float WindowUtils::get_dpi_scale(HWND hwnd) {
    UINT dpi = get_dpi_for_window(hwnd);
    return dpi / 96.0f;
}

UINT WindowUtils::get_dpi_for_window(HWND hwnd) {
    return GetDpiForWindow(hwnd);
}

LRESULT CALLBACK WindowUtils::overlay_wnd_proc(HWND hwnd, UINT msg, WPARAM wparam, LPARAM lparam) {
    // Forward to ImGui
    if (ImGui_ImplWin32_WndProcHandler(hwnd, msg, wparam, lparam)) {
        return TRUE;
    }
    return DefWindowProcW(hwnd, msg, wparam, lparam);
}

bool WindowUtils::setup_message_hook(HWND hwnd, std::function<LRESULT(UINT, WPARAM, LPARAM)> callback) {
    // Subclass window
    SetWindowSubclass(hwnd, [](HWND h, UINT msg, WPARAM wp, LPARAM lp, UINT_PTR id, DWORD_PTR ref) -> LRESULT {
        auto callback = reinterpret_cast<std::function<LRESULT(UINT, WPARAM, LPARAM)>*>(ref);
        if (callback && *callback) {
            LRESULT result = (*callback)(msg, wp, lp);
            if (result != 0) return result;
        }
        return DefSubclassProc(h, msg, wp, lp);
    }, 0, reinterpret_cast<DWORD_PTR>(new std::function<LRESULT(UINT, WPARAM, LPARAM)>(std::move(callback))));
    return true;
}

void WindowUtils::remove_message_hook(HWND hwnd) {
    RemoveWindowSubclass(hwnd, [](HWND, UINT, WPARAM, LPARAM, UINT_PTR, DWORD_PTR) -> LRESULT { return 0; }, 0);
}

BOOL CALLBACK WindowUtils::enum_windows_callback(HWND hwnd, LPARAM lparam) {
    return TRUE;
}

