#include "pattern_scan.hpp"
#include <windows.h>
#include <psapi.h>
#include <algorithm>
#include <cctype>
#include <sstream>

#pragma comment(lib, "psapi.lib")

namespace dx_hook::utils {

std::optional<uintptr_t> PatternScanner::find_pattern(const std::string& module_name, const std::string& pattern, const std::string& mask) {
    HMODULE module = GetModuleHandleA(module_name.c_str());
    if (!module) return std::nullopt;

    MODULEINFO info = {};
    GetModuleInformation(GetCurrentProcess(), module, &info, sizeof(info));

    return find_pattern(reinterpret_cast<uintptr_t>(module), info.SizeOfImage, pattern, mask);
}

std::optional<uintptr_t> PatternScanner::find_pattern(uintptr_t start, size_t length, const std::string& pattern, const std::string& mask) {
    std::vector<uint8_t> pattern_bytes(pattern.begin(), pattern.end());
    std::vector<uint8_t> mask_bytes;

    if (mask.empty()) {
        mask_bytes.assign(pattern_bytes.size(), 0xFF);
    } else {
        mask_bytes.assign(mask.begin(), mask.end());
    }

    if (pattern_bytes.size() != mask_bytes.size()) return std::nullopt;

    const uint8_t* scan_start = reinterpret_cast<const uint8_t*>(start);
    const uint8_t* scan_end = scan_start + length - pattern_bytes.size();

    for (const uint8_t* ptr = scan_start; ptr <= scan_end; ++ptr) {
        if (pattern_match(ptr, pattern_bytes.data(), mask_bytes.data(), pattern_bytes.size())) {
            return reinterpret_cast<uintptr_t>(ptr);
        }
    }

    return std::nullopt;
}

std::vector<uintptr_t> PatternScanner::find_all_patterns(const std::string& module_name, const std::string& pattern, const std::string& mask) {
    std::vector<uintptr_t> results;
    HMODULE module = GetModuleHandleA(module_name.c_str());
    if (!module) return results;

    MODULEINFO info = {};
    GetModuleInformation(GetCurrentProcess(), module, &info, sizeof(info));

    std::vector<uint8_t> pattern_bytes(pattern.begin(), pattern.end());
    std::vector<uint8_t> mask_bytes(mask.empty() ? std::vector<uint8_t>(pattern_bytes.size(), 0xFF) : std::vector<uint8_t>(mask.begin(), mask.end()));

    const uint8_t* scan_start = reinterpret_cast<const uint8_t*>(module);
    const uint8_t* scan_end = scan_start + info.SizeOfImage - pattern_bytes.size();

    for (const uint8_t* ptr = scan_start; ptr <= scan_end; ++ptr) {
        if (pattern_match(ptr, pattern_bytes.data(), mask_bytes.data(), pattern_bytes.size())) {
            results.push_back(reinterpret_cast<uintptr_t>(ptr));
        }
    }

    return results;
}

std::optional<uintptr_t> PatternScanner::find_ida_pattern(const std::string& module_name, const std::string& ida_pattern) {
    auto [pattern_bytes, mask_bytes] = parse_ida_pattern(ida_pattern);
    return find_pattern(module_name, 
        std::string(pattern_bytes.begin(), pattern_bytes.end()),
        std::string(mask_bytes.begin(), mask_bytes.end()));
}

std::vector<uintptr_t> PatternScanner::find_all_ida_patterns(const std::string& module_name, const std::string& ida_pattern) {
    std::vector<uintptr_t> results;
    auto [pattern_bytes, mask_bytes] = parse_ida_pattern(ida_pattern);

    HMODULE module = GetModuleHandleA(module_name.c_str());
    if (!module) return results;

    MODULEINFO info = {};
    GetModuleInformation(GetCurrentProcess(), module, &info, sizeof(info));

    const uint8_t* scan_start = reinterpret_cast<const uint8_t*>(module);
    const uint8_t* scan_end = scan_start + info.SizeOfImage - pattern_bytes.size();

    for (const uint8_t* ptr = scan_start; ptr <= scan_end; ++ptr) {
        if (pattern_match(ptr, pattern_bytes.data(), mask_bytes.data(), pattern_bytes.size())) {
            results.push_back(reinterpret_cast<uintptr_t>(ptr));
        }
    }

    return results;
}

uintptr_t PatternScanner::resolve_relative_call(uintptr_t instruction_address, int offset) {
    // CALL rel32: E8 xx xx xx xx
    int32_t rel = *reinterpret_cast<int32_t*>(instruction_address + offset);
    return instruction_address + offset + 4 + rel;
}

uintptr_t PatternScanner::resolve_relative_jmp(uintptr_t instruction_address, int offset) {
    // JMP rel32: E9 xx xx xx xx
    int32_t rel = *reinterpret_cast<int32_t*>(instruction_address + offset);
    return instruction_address + offset + 4 + rel;
}

std::optional<uintptr_t> PatternScanner::find_vtable(const std::string& module_name, const std::string& rtti_name) {
    // Scan for RTTI Complete Object Locator
    // This is complex - simplified version
    return std::nullopt;
}

std::optional<uintptr_t> PatternScanner::get_vtable_function(uintptr_t vtable, size_t index) {
    if (!vtable) return std::nullopt;
    uintptr_t* vtable_ptr = reinterpret_cast<uintptr_t*>(vtable);
    return vtable_ptr[index];
}

bool PatternScanner::pattern_match(const uint8_t* data, const uint8_t* pattern, const uint8_t* mask, size_t length) {
    for (size_t i = 0; i < length; ++i) {
        if (mask[i] && data[i] != pattern[i]) {
            return false;
        }
    }
    return true;
}

std::pair<std::vector<uint8_t>, std::vector<uint8_t>> PatternScanner::parse_ida_pattern(const std::string& pattern) {
    std::vector<uint8_t> bytes;
    std::vector<uint8_t> mask;

    std::istringstream iss(pattern);
    std::string token;

    while (iss >> token) {
        if (token == "?" || token == "??") {
            bytes.push_back(0);
            mask.push_back(0);
        } else {
            uint8_t byte = static_cast<uint8_t>(std::stoul(token, nullptr, 16));
            bytes.push_back(byte);
            mask.push_back(0xFF);
        }
    }

    return {bytes, mask};
}

