#include "hook/hook_manager.hpp"
#include "imgui/imgui_context.hpp"
#include "utils/window_utils.hpp"
#include <windows.h>
#include <thread>
#include <atomic>

namespace dx_hook {

static std::atomic<bool> g_running{false};
static std::thread g_main_thread;
static HookManager::HookConfig g_config;

DWORD WINAPI main_thread_func(LPVOID param) {
    auto& manager = HookManager::instance();

    // Wait for target window
    HWND target_window = g_config.target_window;
    if (!target_window) {
        // Try to find game window
        target_window = WindowUtils::find_game_window_by_pid(GetCurrentProcessId());
    }

    if (!target_window) {
        // Wait for window creation
        for (int i = 0; i < 100 && !target_window; ++i) {
            std::this_thread::sleep_for(std::chrono::milliseconds(100));
            target_window = WindowUtils::find_game_window_by_pid(GetCurrentProcessId());
        }
    }

    if (target_window) {
        g_config.target_window = target_window;
        manager.initialize(g_config);
    }

    // Keep thread alive
    while (g_running.load()) {
        std::this_thread::sleep_for(std::chrono::milliseconds(100));
    }

    manager.shutdown();
    return 0;
}

extern "C" __declspec(dllexport) bool InitializeHook(const HookManager::HookConfig& config) {
    if (g_running.exchange(true)) return false;

    g_config = config;
    g_main_thread = std::thread(main_thread_func, nullptr);
    return true;
}

extern "C" __declspec(dllexport) void ShutdownHook() {
    if (!g_running.exchange(false)) return;

    if (g_main_thread.joinable()) {
        g_main_thread.join();
    }
}

extern "C" __declspec(dllexport) bool IsHookActive() {
    return HookManager::instance().is_initialized();
}

extern "C" __declspec(dllexport) void SetImGuiRenderCallback(std::function<void()> callback) {
    HookManager::instance().set_imgui_render_callback(std::move(callback));
}

} // namespace dx_hook
