// Math/Vec2.hpp
#pragma once
#include <cmath>
#include <algorithm>

struct Vec2 {
    float x, y;

    constexpr Vec2() : x(0), y(0) {}
    constexpr Vec2(float x_, float y_) : x(x_), y(y_) {}

    Vec2& operator+=(const Vec2& o) { x += o.x; y += o.y; return *this; }
    Vec2& operator-=(const Vec2& o) { x -= o.x; y -= o.y; return *this; }
    Vec2& operator*=(float s) { x *= s; y *= s; return *this; }
    Vec2& operator/=(float s) { x /= s; y /= s; return *this; }

    friend Vec2 operator+(Vec2 a, const Vec2& b) { return a += b; }
    friend Vec2 operator-(Vec2 a, const Vec2& b) { return a -= b; }
    friend Vec2 operator*(Vec2 a, float s) { return a *= s; }
    friend Vec2 operator*(float s, Vec2 a) { return a *= s; }
    friend Vec2 operator/(Vec2 a, float s) { return a /= s; }

    float Length() const { return std::sqrt(x*x + y*y); }
    float LengthSq() const { return x*x + y*y; }
    Vec2 Normalized() const { float l = Length(); return l > 0 ? *this / l : Vec2(0,0); }
};

struct Vec3 {
    float x, y, z;
    constexpr Vec3() : x(0), y(0), z(0) {}
    constexpr Vec3(float x_, float y_, float z_) : x(x_), y(y_), z(z_) {}
};

struct Vec4 {
    float x, y, z, w;
    constexpr Vec4() : x(0), y(0), z(0), w(1) {}
    constexpr Vec4(float x_, float y_, float z_, float w_) : x(x_), y(y_), z(z_), w(w_) {}
    constexpr Vec4(const Vec3& v, float w_) : x(v.x), y(v.y), z(v.z), w(w_) {}
};

struct Matrix4x4 {
    float m[4][4];

    static Matrix4x4 Identity() {
        Matrix4x4 r{};
        for (int i = 0; i < 4; ++i) r.m[i][i] = 1.0f;
        return r;
    }

    Vec4 Transform(const Vec4& v) const {
        return Vec4(
            m[0][0]*v.x + m[0][1]*v.y + m[0][2]*v.z + m[0][3]*v.w,
            m[1][0]*v.x + m[1][1]*v.y + m[1][2]*v.z + m[1][3]*v.w,
            m[2][0]*v.x + m[2][1]*v.y + m[2][2]*v.z + m[2][3]*v.w,
            m[3][0]*v.x + m[3][1]*v.y + m[3][2]*v.z + m[3][3]*v.w
        );
    }

    Vec3 TransformPoint(const Vec3& v) const {
        Vec4 r = Transform(Vec4(v, 1.0f));
        if (r.w != 0.0f) r = Vec4(r.x/r.w, r.y/r.w, r.z/r.w, 1.0f);
        return Vec3(r.x, r.y, r.z);
    }
};
