### Color System

```cpp
// Render/Color.hpp
#pragma once
#include <cstdint>
#include <algorithm>

struct Color {
    uint8_t r, g, b, a;

    constexpr Color() : r(0), g(0), b(0), a(255) {}
    constexpr Color(uint8_t r_, uint8_t g_, uint8_t b_, uint8_t a_ = 255) 
        : r(r_), g(g_), b(b_), a(a_) {}
    constexpr Color(uint32_t rgba) 
        : r((rgba >> 24) & 0xFF), g((rgba >> 16) & 0xFF), 
          b((rgba >> 8) & 0xFF), a(rgba & 0xFF) {}

    // From ImVec4 (0-1 range)
    static Color FromFloat(float r, float g, float b, float a = 1.0f) {
        return Color(
            static_cast<uint8_t>(std::clamp(r, 0.0f, 1.0f) * 255.0f),
            static_cast<uint8_t>(std::clamp(g, 0.0f, 1.0f) * 255.0f),
            static_cast<uint8_t>(std::clamp(b, 0.0f, 1.0f) * 255.0f),
            static_cast<uint8_t>(std::clamp(a, 0.0f, 1.0f) * 255.0f)
        );
    }

    // HSV to RGB
    static Color FromHSV(float h, float s, float v, float a = 1.0f) {
        float c = v * s;
        float x = c * (1 - std::abs(std::fmod(h / 60.0f, 2) - 1));
        float m = v - c;
        float r, g, b;

        if (h < 60) { r = c; g = x; b = 0; }
        else if (h < 120) { r = x; g = c; b = 0; }
        else if (h < 180) { r = 0; g = c; b = x; }
        else if (h < 240) { r = 0; g = x; b = c; }
        else if (h < 300) { r = x; g = 0; b = c; }
        else { r = c; g = 0; b = x; }

        return FromFloat(r + m, g + m, b + m, a);
    }

    // Lerp between colors
    static Color Lerp(const Color& a, const Color& b, float t) {
        t = std::clamp(t, 0.0f, 1.0f);
        return Color(
            static_cast<uint8_t>(a.r + (b.r - a.r) * t),
            static_cast<uint8_t>(a.g + (b.g - a.g) * t),
            static_cast<uint8_t>(a.b + (b.b - a.b) * t),
            static_cast<uint8_t>(a.a + (b.a - a.a) * t)
        );
    }

    // Health-based color (red -> yellow -> green)
    static Color HealthColor(float healthPercent) {
        healthPercent = std::clamp(healthPercent, 0.0f, 1.0f);
        if (healthPercent > 0.5f) {
            return Lerp(Color(255, 255, 0), Color(0, 255, 0), (healthPercent - 0.5f) * 2.0f);
        } else {
            return Lerp(Color(255, 0, 0), Color(255, 255, 0), healthPercent * 2.0f);
        }
    }

    // To ImVec4
    ImVec4 ToImVec4() const {
        return ImVec4(r / 255.0f, g / 255.0f, b / 255.0f, a / 255.0f);
    }

    // To ImU32 (ABGR format for ImDrawList)
    ImU32 ToImU32() const {
        return IM_COL32(r, g, b, a);
    }

    // Predefined colors
    static const Color White;
    static const Color Black;
    static const Color Red;
    static const Color Green;
    static const Color Blue;
    static const Color Yellow;
    static const Color Cyan;
    static const Color Magenta;
    static const Color Orange;
    static const Color Purple;
    static const Color Transparent;
};
