### D3D11 Implementation (Windows)

```cpp
// Render/D3D11Renderer.cpp
#include "Renderer2D.hpp"
#include <d3d11.h>
#include <dxgi.h>
#include <imgui.h>
#include <imgui_impl_dx11.h>
#include <imgui_impl_win32.h>
#include <wrl/client.h>
#include <vector>

using Microsoft::WRL::ComPtr;

class D3D11Renderer : public Renderer2D {
public:
    bool Initialize(void* windowHandle, int width, int height) override {
        HWND hwnd = static_cast<HWND>(windowHandle);
        m_hwnd = hwnd;

        // Create device and swap chain
        DXGI_SWAP_CHAIN_DESC scd{};
        scd.BufferCount = 2;
        scd.BufferDesc.Width = width;
        scd.BufferDesc.Height = height;
        scd.BufferDesc.Format = DXGI_FORMAT_R8G8B8A8_UNORM;
        scd.BufferDesc.RefreshRate.Numerator = 60;
        scd.BufferDesc.RefreshRate.Denominator = 1;
        scd.BufferUsage = DXGI_USAGE_RENDER_TARGET_OUTPUT;
        scd.OutputWindow = hwnd;
        scd.SampleDesc.Count = 1;
        scd.SampleDesc.Quality = 0;
        scd.Windowed = TRUE;
        scd.SwapEffect = DXGI_SWAP_EFFECT_FLIP_DISCARD;
        scd.Flags = DXGI_SWAP_CHAIN_FLAG_ALLOW_MODE_SWITCH;

        D3D_FEATURE_LEVEL featureLevels[] = {
            D3D_FEATURE_LEVEL_11_1,
            D3D_FEATURE_LEVEL_11_0,
            D3D_FEATURE_LEVEL_10_1,
            D3D_FEATURE_LEVEL_10_0
        };

        HRESULT hr = D3D11CreateDeviceAndSwapChain(
            nullptr, D3D_DRIVER_TYPE_HARDWARE, nullptr,
            D3D11_CREATE_DEVICE_BGRA_SUPPORT,
            featureLevels, ARRAYSIZE(featureLevels),
            D3D11_SDK_VERSION, &scd,
            &m_swapChain, &m_device, nullptr, &m_context
        );

        if (FAILED(hr)) return false;

        CreateRenderTarget();
        InitializeImGui();
        CreateShaders();
        CreateGeometryBuffers();
        CreateFontTexture();

        m_initialized = true;
        return true;
    }

    void Shutdown() override {
        ImGui_ImplDX11_Shutdown();
        ImGui_ImplWin32_Shutdown();
        ImGui::DestroyContext();

        m_swapChain.Reset();
        m_context.Reset();
        m_device.Reset();
        m_initialized = false;
    }

    void BeginFrame() override {
        m_context->OMSetRenderTargets(1, m_renderTargetView.GetAddressOf(), nullptr);

        float clearColor[4] = {0, 0, 0, 0};
        m_context->ClearRenderTargetView(m_renderTargetView.Get(), clearColor);

        ImGui_ImplDX11_NewFrame();
        ImGui_ImplWin32_NewFrame();
        ImGui::NewFrame();

        m_drawList = ImGui::GetBackgroundDrawList();
    }

    void EndFrame() override {
        ImGui::Render();
        ImGui_ImplDX11_RenderDrawData(ImGui::GetDrawData());
        m_swapChain->Present(1, 0); // VSync
    }

    void Resize(int width, int height) override {
        if (!m_initialized) return;

        ImGui_ImplDX11_InvalidateDeviceObjects();
        m_renderTargetView.Reset();

        m_swapChain->ResizeBuffers(0, width, height, DXGI_FORMAT_UNKNOWN, 0);
        CreateRenderTarget();

        ImGui_ImplDX11_CreateDeviceObjects();
    }

    // Drawing primitives using ImDrawList
    void DrawLine(const Vec2& from, const Vec2& to, const Color& color, float thickness) override {
        m_drawList->AddLine(ImVec2(from.x, from.y), ImVec2(to.x, to.y), color.ToImU32(), thickness);
    }

    void DrawRect(const Vec2& min, const Vec2& max, const Color& color, float thickness) override {
        m_drawList->AddRect(ImVec2(min.x, min.y), ImVec2(max.x, max.y), color.ToImU32(), 0.0f, 0, thickness);
    }

    void DrawRectFilled(const Vec2& min, const Vec2& max, const Color& color) override {
        m_drawList->AddRectFilled(ImVec2(min.x, min.y), ImVec2(max.x, max.y), color.ToImU32());
    }

    void DrawRectRounded(const Vec2& min, const Vec2& max, const Color& color, float rounding, float thickness) override {
        m_drawList->AddRect(ImVec2(min.x, min.y), ImVec2(max.x, max.y), color.ToImU32(), rounding, 0, thickness);
    }

    void DrawRectFilledRounded(const Vec2& min, const Vec2& max, const Color& color, float rounding) override {
        m_drawList->AddRectFilled(ImVec2(min.x, min.y), ImVec2(max.x, max.y), color.ToImU32(), rounding);
    }

    void DrawCircle(const Vec2& center, float radius, const Color& color, float thickness, int segments) override {
        m_drawList->AddCircle(ImVec2(center.x, center.y), radius, color.ToImU32(), segments, thickness);
    }

    void DrawCircleFilled(const Vec2& center, float radius, const Color& color, int segments) override {
        m_drawList->AddCircleFilled(ImVec2(center.x, center.y), radius, color.ToImU32(), segments);
    }

    void DrawTriangle(const Vec2& a, const Vec2& b, const Vec2& c, const Color& color, float thickness) override {
        m_drawList->AddTriangle(ImVec2(a.x, a.y), ImVec2(b.x, b.y), ImVec2(c.x, c.y), color.ToImU32(), thickness);
    }

    void DrawTriangleFilled(const Vec2& a, const Vec2& b, const Vec2& c, const Color& color) override {
        m_drawList->AddTriangleFilled(ImVec2(a.x, a.y), ImVec2(b.x, b.y), ImVec2(c.x, c.y), color.ToImU32());
    }

    void DrawPolyLine(const Vec2* points, int count, const Color& color, float thickness, bool closed) override {
        std::vector<ImVec2> imPoints(count);
        for (int i = 0; i < count; ++i) {
            imPoints[i] = ImVec2(points[i].x, points[i].y);
        }
        m_drawList->AddPolyline(imPoints.data(), count, color.ToImU32(), closed, thickness);
    }

    void DrawPolyLineFilled(const Vec2* points, int count, const Color& color) override {
        std::vector<ImVec2> imPoints(count);
        for (int i = 0; i < count; ++i) {
            imPoints[i] = ImVec2(points[i].x, points[i].y);
        }
        m_drawList->AddConvexPolyFilled(imPoints.data(), count, color.ToImU32());
    }

    void DrawText(const Vec2& pos, const char* text, const Color& color, float fontSize, bool centered) override {
        ImFont* font = ImGui::GetFont();
        float scale = fontSize / font->FontSize;

        Vec2 textSize = MeasureText(text, fontSize);
        Vec2 drawPos = pos;
        if (centered) drawPos.x -= textSize.x * 0.5f;

        m_drawList->AddText(font, fontSize, ImVec2(drawPos.x, drawPos.y), color.ToImU32(), text);
    }

    Vec2 MeasureText(const char* text, float fontSize) override {
        ImFont* font = ImGui::GetFont();
        ImVec2 size = font->CalcTextSizeA(fontSize, FLT_MAX, 0.0f, text);
        return Vec2(size.x, size.y);
    }

    void* CreateTexture(const uint8_t* data, int width, int height) override {
        ComPtr<ID3D11Texture2D> texture;
        D3D11_TEXTURE2D_DESC desc{};
        desc.Width = width;
        desc.Height = height;
        desc.MipLevels = 1;
        desc.ArraySize = 1;
        desc.Format = DXGI_FORMAT_R8G8B8A8_UNORM;
        desc.SampleDesc.Count = 1;
        desc.Usage = D3D11_USAGE_DEFAULT;
        desc.BindFlags = D3D11_BIND_SHADER_RESOURCE;

        D3D11_SUBRESOURCE_DATA subData{};
        subData.pSysMem = data;
        subData.SysMemPitch = width * 4;

        HRESULT hr = m_device->CreateTexture2D(&desc, &subData, &texture);
        if (FAILED(hr)) return nullptr;

        ComPtr<ID3D11ShaderResourceView> srv;
        D3D11_SHADER_RESOURCE_VIEW_DESC srvDesc{};
        srvDesc.Format = DXGI_FORMAT_R8G8B8A8_UNORM;
        srvDesc.ViewDimension = D3D11_SRV_DIMENSION_TEXTURE2D;
        srvDesc.Texture2D.MipLevels = 1;

        hr = m_device->CreateShaderResourceView(texture.Get(), &srvDesc, &srv);
        if (FAILED(hr)) return nullptr;

        // Store both texture and SRV
        auto* handle = new TextureHandle{texture, srv};
        return handle;
    }

    void DestroyTexture(void* texture) override {
        delete static_cast<TextureHandle*>(texture);
    }

    void DrawImage(void* texture, const Vec2& min, const Vec2& max, const Color& tint) override {
        auto* handle = static_cast<TextureHandle*>(texture);
        m_drawList->AddImage(handle->srv.Get(), ImVec2(min.x, min.y), ImVec2(max.x, max.y), 
                            ImVec2(0, 0), ImVec2(1, 1), tint.ToImU32());
    }

    void DrawImageUV(void* texture, const Vec2& min, const Vec2& max, 
                     const Vec2& uvMin, const Vec2& uvMax, const Color& tint) override {
        auto* handle = static_cast<TextureHandle*>(texture);
        m_drawList->AddImage(handle->srv.Get(), ImVec2(min.x, min.y), ImVec2(max.x, max.y),
                            ImVec2(uvMin.x, uvMin.y), ImVec2(uvMax.x, uvMax.y), tint.ToImU32());
    }

    void PushClipRect(const Vec2& min, const Vec2& max, bool intersect) override {
        m_drawList->PushClipRect(ImVec2(min.x, min.y), ImVec2(max.x, max.y), intersect);
    }

    void PopClipRect() override {
        m_drawList->PopClipRect();
    }

    Vec2 GetViewportSize() const override {
        RECT rect;
        GetClientRect(m_hwnd, &rect);
        return Vec2(float(rect.right - rect.left), float(rect.bottom - rect.top));
    }

    float GetDPIScale() const override {
        return ImGui::GetIO().FontGlobalScale;
    }

