### ESP Drawing Components (Educational - For Overlay/Debug Visualization)

```cpp
// ESP/ESPDrawer.hpp
#pragma once
#include "Renderer2D.hpp"
#include "Vec2.hpp"
#include "Color.hpp"
#include <vector>
#include <string>
#include <optional>

struct Box2D {
    Vec2 min, max;
    Color color = Color::White;
    float thickness = 2.0f;
    bool filled = false;
    float fillAlpha = 0.15f;
    float rounding = 0.0f;

    Vec2 Center() const { return (min + max) * 0.5f; }
    Vec2 Size() const { return max - min; }
    float Width() const { return max.x - min.x; }
    float Height() const { return max.y - min.y; }
};

struct HealthBar {
    Vec2 position;      // Top-left of bar background
    Vec2 size;          // Width, height
    float healthPercent; // 0.0 - 1.0
    Color bgColor = Color(30, 30, 30, 200);
    Color borderColor = Color(60, 60, 60, 255);
    float rounding = 2.0f;
    bool vertical = false;
    bool showText = true;
    float textSize = 10.0f;
};

struct SkeletonBone {
    Vec2 start, end;
    Color color = Color::White;
    float thickness = 2.0f;
};

struct Skeleton {
    std::vector<SkeletonBone> bones;
    Color defaultColor = Color::White;
    float defaultThickness = 2.0f;

    // Standard bone connections (indices into a joint array)
    static const std::vector<std::pair<int, int>> StandardConnections;
};

struct Snapline {
    Vec2 from;          // Screen center or custom origin
    Vec2 to;            // Target position
    Color color = Color::White;
    float thickness = 1.5f;
    bool dashed = false;
    float dashLength = 8.0f;
    float gapLength = 4.0f;
};

struct ESPText {
    Vec2 position;
    std::string text;
    Color color = Color::White;
    float fontSize = 12.0f;
    bool centered = true;
    bool outline = true;
    Color outlineColor = Color::Black;
    Vec2 offset = Vec2(0, 0);
};

class ESPDrawer {
public:
    explicit ESPDrawer(Renderer2D* renderer) : m_renderer(renderer) {}

    // 2D Boxes
    void DrawBox(const Box2D& box) {
        if (box.filled) {
            Color fillColor = box.color;
            fillColor.a = static_cast<uint8_t>(box.color.a * box.fillAlpha);
            m_renderer->DrawRectFilledRounded(box.min, box.max, fillColor, box.rounding);
        }
        m_renderer->DrawRectRounded(box.min, box.max, box.color, box.rounding, box.thickness);
    }

    void DrawCorneredBox(const Box2D& box, float cornerSize = 0.0f) {
        if (cornerSize <= 0) cornerSize = std::min(box.Width(), box.Height()) * 0.15f;

        Vec2 min = box.min;
        Vec2 max = box.max;
        float w = box.Width();
        float h = box.Height();
        float cs = std::min(cornerSize, std::min(w, h) * 0.5f);

        // Top-left
        m_renderer->DrawLine(min, Vec2(min.x + cs, min.y), box.color, box.thickness);
        m_renderer->DrawLine(min, Vec2(min.x, min.y + cs), box.color, box.thickness);
        // Top-right
        m_renderer->DrawLine(Vec2(max.x, min.y), Vec2(max.x - cs, min.y), box.color, box.thickness);
        m_renderer->DrawLine(Vec2(max.x, min.y), Vec2(max.x, min.y + cs), box.color, box.thickness);
        // Bottom-left
        m_renderer->DrawLine(Vec2(min.x, max.y), Vec2(min.x + cs, max.y), box.color, box.thickness);
        m_renderer->DrawLine(Vec2(min.x, max.y), Vec2(min.x, max.y - cs), box.color, box.thickness);
        // Bottom-right
        m_renderer->DrawLine(max, Vec2(max.x - cs, max.y), box.color, box.thickness);
        m_renderer->DrawLine(max, Vec2(max.x, max.y - cs), box.color, box.thickness);
    }

    void DrawFilledBox(const Box2D& box, const Color& fillColor) {
        m_renderer->DrawRectFilledRounded(box.min, box.max, fillColor, box.rounding);
        m_renderer->DrawRectRounded(box.min, box.max, box.color, box.rounding, box.thickness);
    }

    // Health Bars
    void DrawHealthBar(const HealthBar& bar) {
        Vec2 bgMin = bar.position;
        Vec2 bgMax = bar.position + bar.size;

        // Background
        m_renderer->DrawRectFilledRounded(bgMin, bgMax, bar.bgColor, bar.rounding);
        m_renderer->DrawRectRounded(bgMin, bgMax, bar.borderColor, bar.rounding, 1.0f);

        // Health fill
        float health = std::clamp(bar.healthPercent, 0.0f, 1.0f);
        Color healthColor = Color::HealthColor(health);

        Vec2 fillMin, fillMax;
        if (bar.vertical) {
            float fillHeight = bar.size.y * health;
            fillMin = Vec2(bgMin.x + 1, bgMax.y - fillHeight - 1);
            fillMax = Vec2(bgMax.x - 1, bgMax.y - 1);
        } else {
            float fillWidth = bar.size.x * health;
            fillMin = Vec2(bgMin.x + 1, bgMin.y + 1);
            fillMax = Vec2(bgMin.x + fillWidth - 1, bgMax.y - 1);
        }

        if (fillMax.x > fillMin.x && fillMax.y > fillMin.y) {
            m_renderer->DrawRectFilledRounded(fillMin, fillMax, healthColor, bar.rounding - 1);
        }

        // Health text
        if (bar.showText && health > 0.0f) {
            char buf[16];
            snprintf(buf, sizeof(buf), "%.0f%%", health * 100.0f);
            Vec2 textPos = bar.position + bar.size * 0.5f;
            m_renderer->DrawText(textPos, buf, Color::White, bar.textSize, true);
        }
    }

    // Skeleton/Bones
    void DrawSkeleton(const Skeleton& skeleton, const std::vector<Vec2>& joints) {
        for (const auto& bone : skeleton.bones) {
            if (bone.start.x == 0 && bone.start.y == 0 && bone.end.x == 0 && bone.end.y == 0) continue;
            m_renderer->DrawLine(bone.start, bone.end, bone.color, bone.thickness);
        }
    }

    void DrawSkeletonFromJoints(const std::vector<Vec2>& joints, 
                                 const std::vector<std::pair<int, int>>& connections,
                                 const Color& color, float thickness) {
        for (const auto& conn : connections) {
            int a = conn.first;
            int b = conn.second;
            if (a >= 0 && a < (int)joints.size() && b >= 0 && b < (int)joints.size()) {
                const Vec2& ja = joints[a];
                const Vec2& jb = joints[b];
                if (ja.x != 0 || ja.y != 0 || jb.x != 0 || jb.y != 0) {
                    m_renderer->DrawLine(ja, jb, color, thickness);
                }
            }
        }

        // Draw joint dots
        for (const auto& joint : joints) {
            if (joint.x != 0 || joint.y != 0) {
                m_renderer->DrawCircleFilled(joint, thickness * 1.5f, color, 8);
            }
        }
    }

    // Snaplines
    void DrawSnapline(const Snapline& line) {
        if (line.dashed) {
            DrawDashedLine(line.from, line.to, line.color, line.thickness, 
                          line.dashLength, line.gapLength);
        } else {
            m_renderer->DrawLine(line.from, line.to, line.color, line.thickness);
        }
    }

    void DrawSnaplinesToTargets(const Vec2& origin, const std::vector<Vec2>& targets, 
                                 const Color& color, float thickness, bool dashed = false) {
        for (const auto& target : targets) {
            Snapline line;
            line.from = origin;
            line.to = target;
            line.color = color;
            line.thickness = thickness;
            line.dashed = dashed;
            DrawSnapline(line);
        }
    }

    // Text with outline
    void DrawText(const ESPText& text) {
        Vec2 pos = text.position + text.offset;

        if (text.outline) {
            // Draw outline (4 directions)
            m_renderer->DrawText(Vec2(pos.x + 1, pos.y), text.text.c_str(), text.outlineColor, text.fontSize, text.centered);
            m_renderer->DrawText(Vec2(pos.x - 1, pos.y), text.text.c_str(), text.outlineColor, text.fontSize, text.centered);
            m_renderer->DrawText(Vec2(pos.x, pos.y + 1), text.text.c_str(), text.outlineColor, text.fontSize, text.centered);
            m_renderer->DrawText(Vec2(pos.x, pos.y - 1), text.text.c_str(), text.outlineColor, text.fontSize, text.centered);
            // Diagonals for thicker outline
            m_renderer->DrawText(Vec2(pos.x + 1, pos.y + 1), text.text.c_str(), text.outlineColor, text.fontSize, text.centered);
            m_renderer->DrawText(Vec2(pos.x - 1, pos.y - 1), text.text.c_str(), text.outlineColor, text.fontSize, text.centered);
            m_renderer->DrawText(Vec2(pos.x + 1, pos.y - 1), text.text.c_str(), text.outlineColor, text.fontSize, text.centered);
            m_renderer->DrawText(Vec2(pos.x - 1, pos.y + 1), text.text.c_str(), text.outlineColor, text.fontSize, text.centered);
        }

        m_renderer->DrawText(pos, text.text.c_str(), text.color, text.fontSize, text.centered);
    }

    // Distance-based scaling
    void DrawDistanceScaledBox(const Box2D& box, float distance, float maxDistance, float minScale = 0.3f) {
        float scale = std::clamp(1.0f - (distance / maxDistance), minScale, 1.0f);
        Box2D scaled = box;
        Vec2 center = box.Center();
        Vec2 halfSize = box.Size() * 0.5f * scale;
        scaled.min = center - halfSize;
        scaled.max = center + halfSize;
        scaled.thickness = box.thickness * scale;
        DrawBox(scaled);
    }

    // Off-screen indicator (arrow pointing to off-screen target)
    void DrawOffScreenIndicator(const Vec2& screenCenter, const Vec2& targetPos, 
                                 float distance, const Color& color, float size = 20.0f) {
        Vec2 dir = (targetPos - screenCenter).Normalized();
        Vec2 arrowPos = screenCenter + dir * (std::min(screenCenter.x, screenCenter.y) - size * 2);

        // Arrow triangle
        Vec2 forward = dir * size;
        Vec2 right = Vec2(-dir.y, dir.x) * size * 0.6f;

        Vec2 tip = arrowPos + forward;
        Vec2 left = arrowPos - forward * 0.5f + right;
        Vec2 rightPt = arrowPos - forward * 0.5f - right;

        m_renderer->DrawTriangleFilled(tip, left, rightPt, color);
        m_renderer->DrawTriangle(tip, left, rightPt, Color::Black, 2.0f);

        // Distance text
        char buf[32];
        snprintf(buf, sizeof(buf), "%.0fm", distance);
        m_renderer->DrawText(arrowPos - forward * 0.8f - Vec2(0, 15), buf, color, 11.0f, true);
    }

private:
    void DrawDashedLine(const Vec2& from, const Vec2& to, const Color& color, 
                        float thickness, float dashLen, float gapLen) {
        Vec2 dir = to - from;
        float length = dir.Length();
        if (length <= 0) return;

        dir /= length;
        float pos = 0.0f;
        bool draw = true;

        while (pos < length) {
            float segmentLen = draw ? dashLen : gapLen;
            float endPos = std::min(pos + segmentLen, length);

            if (draw) {
                Vec2 start = from + dir * pos;
                Vec2 end = from + dir * endPos;
                m_renderer->DrawLine(start, end, color, thickness);
            }

            pos += segmentLen;
            draw = !draw;
        }
    }

    Renderer2D* m_renderer;
};

// Standard skeleton connections (COCO format - 17 keypoints)
const std::vector<std::pair<int, int>> Skeleton::StandardConnections = {
    {0, 1}, {0, 2}, {1, 3}, {2, 4},           // Head
    {5, 6}, {5, 7}, {7, 9}, {6, 8}, {8, 10},  // Arms
    {5, 11}, {6, 12}, {11, 12},               // Torso
    {11, 13}, {13, 15}, {12, 14}, {14, 16}    // Legs
};
