### World-to-Screen Projection

```cpp
// ESP/WorldToScreen.hpp
#pragma once
#include "Vec2.hpp"
#include "Vec3.hpp"
#include "Matrix4x4.hpp"
#include <optional>

class WorldToScreen {
public:
    // View matrix (4x4 row-major or column-major depending on engine)
    Matrix4x4 viewMatrix;
    Matrix4x4 projectionMatrix;
    int screenWidth = 1920;
    int screenHeight = 1080;

    // Convert world position to screen coordinates
    // Returns nullopt if point is behind camera or off-screen
    std::optional<Vec2> Project(const Vec3& worldPos) const {
        // Transform to clip space
        Vec4 clip = viewMatrix.Transform(Vec4(worldPos, 1.0f));
        clip = projectionMatrix.Transform(clip);

        // Check if behind camera
        if (clip.w < 0.01f) return std::nullopt;

        // Perspective divide
        Vec3 ndc = Vec3(clip.x / clip.w, clip.y / clip.w, clip.z / clip.w);

        // Check if in NDC bounds (-1 to 1)
        if (ndc.x < -1.0f || ndc.x > 1.0f || 
            ndc.y < -1.0f || ndc.y > 1.0f ||
            ndc.z < 0.0f || ndc.z > 1.0f) {
            return std::nullopt;
        }

        // Convert to screen coordinates
        float x = (ndc.x + 1.0f) * 0.5f * screenWidth;
        float y = (1.0f - ndc.y) * 0.5f * screenHeight; // Flip Y

        return Vec2(x, y);
    }

    // Project with custom view/projection
    std::optional<Vec2> Project(const Vec3& worldPos, 
                                 const Matrix4x4& view, 
                                 const Matrix4x4& proj) const {
        Vec4 clip = view.Transform(Vec4(worldPos, 1.0f));
        clip = proj.Transform(clip);

        if (clip.w < 0.01f) return std::nullopt;

        Vec3 ndc(clip.x / clip.w, clip.y / clip.w, clip.z / clip.w);

        if (ndc.x < -1.0f || ndc.x > 1.0f || 
            ndc.y < -1.0f || ndc.y > 1.0f) {
            return std::nullopt;
        }

        float x = (ndc.x + 1.0f) * 0.5f * screenWidth;
        float y = (1.0f - ndc.y) * 0.5f * screenHeight;

        return Vec2(x, y);
    }

    // Get screen center
    Vec2 GetScreenCenter() const {
        return Vec2(screenWidth * 0.5f, screenHeight * 0.5f);
    }

    // Check if world position is visible on screen
    bool IsOnScreen(const Vec3& worldPos) const {
        return Project(worldPos).has_value();
    }

    // Get distance from camera to world position
    float GetDistance(const Vec3& worldPos, const Vec3& cameraPos) const {
        Vec3 diff = worldPos - cameraPos;
        return std::sqrt(diff.x*diff.x + diff.y*diff.y + diff.z*diff.z);
    }

    // Calculate 2D bounding box from 3D bounding box
    std::optional<Box2D> CalculateBounds(const Vec3& min3D, const Vec3& max3D) const {
        // 8 corners of 3D box
        Vec3 corners[8] = {
            {min3D.x, min3D.y, min3D.z},
            {max3D.x, min3D.y, min3D.z},
            {min3D.x, max3D.y, min3D.z},
            {max3D.x, max3D.y, min3D.z},
            {min3D.x, min3D.y, max3D.z},
            {max3D.x, min3D.y, max3D.z},
            {min3D.x, max3D.y, max3D.z},
            {max3D.x, max3D.y, max3D.z}
        };

        Vec2 min2D(FLT_MAX, FLT_MAX);
        Vec2 max2D(-FLT_MAX, -FLT_MAX);
        bool anyValid = false;

        for (const auto& corner : corners) {
            if (auto screenPos = Project(corner)) {
                min2D.x = std::min(min2D.x, screenPos->x);
                min2D.y = std::min(min2D.y, screenPos->y);
                max2D.x = std::max(max2D.x, screenPos->x);
                max2D.y = std::max(max2D.y, screenPos->y);
                anyValid = true;
            }
        }

        if (!anyValid) return std::nullopt;

        // Add padding
        float padding = 2.0f;
        min2D -= Vec2(padding, padding);
        max2D += Vec2(padding, padding);

        // Clamp to screen
        min2D.x = std::clamp(min2D.x, 0.0f, (float)screenWidth);
        min2D.y = std::clamp(min2D.y, 0.0f, (float)screenHeight);
        max2D.x = std::clamp(max2D.x, 0.0f, (float)screenWidth);
        max2D.y = std::clamp(max2D.y, 0.0f, (float)screenHeight);

        if (max2D.x <= min2D.x || max2D.y <= min2D.y) return std::nullopt;

        return Box2D{min2D, max2D};
    }
};
