### Overlay Manager (Complete Integration)

```cpp
// Overlay/OverlayManager.hpp
#pragma once
#include "Renderer2D.hpp"
#include "ESPDrawer.hpp"
#include "WorldToScreen.hpp"
#include <memory>
#include <functional>
#include <chrono>

struct OverlayConfig {
    int width = 1920;
    int height = 1080;
    bool vsync = true;
    bool clickThrough = true;  // WS_EX_TRANSPARENT
    bool topMost = true;       // HWND_TOPMOST
    std::string windowClass = "OverlayWindowClass";
    std::string windowTitle = "Overlay";
    RendererBackend backend = RendererBackend::D3D11;
};

class OverlayManager {
public:
    using RenderCallback = std::function<void(Renderer2D*, ESPDrawer*, float deltaTime)>;
    using InputCallback = std::function<void(WPARAM, LPARAM)>;

    OverlayManager() = default;
    ~OverlayManager() { Shutdown(); }

    bool Initialize(const OverlayConfig& config, RenderCallback renderCb) {
        m_config = config;
        m_renderCallback = std::move(renderCb);

        if (!CreateWindow()) return false;
        if (!CreateRenderer()) return false;

        m_running = true;
        m_lastTime = std::chrono::high_resolution_clock::now();

        return true;
    }

    void Shutdown() {
        m_running = false;
        if (m_renderer) m_renderer->Shutdown();
        if (m_hwnd) DestroyWindow(m_hwnd);
        m_hwnd = nullptr;
    }

    void Run() {
        MSG msg{};
        while (m_running && GetMessage(&msg, nullptr, 0, 0)) {
            TranslateMessage(&msg);
            DispatchMessage(&msg);
        }
    }

    void RunSingleFrame() {
        MSG msg{};
        while (PeekMessage(&msg, nullptr, 0, 0, PM_REMOVE)) {
            if (msg.message == WM_QUIT) {
                m_running = false;
                return;
            }
            TranslateMessage(&msg);
            DispatchMessage(&msg);
        }

        RenderFrame();
    }

    HWND GetWindowHandle() const { return m_hwnd; }
    Renderer2D* GetRenderer() const { return m_renderer.get(); }
    ESPDrawer* GetESPDrawer() const { return m_espDrawer.get(); }
    WorldToScreen* GetWorldToScreen() { return &m_worldToScreen; }

    void SetClickThrough(bool enabled) {
        if (!m_hwnd) return;
        LONG exStyle = GetWindowLong(m_hwnd, GWL_EXSTYLE);
        if (enabled) exStyle |= WS_EX_TRANSPARENT | WS_EX_LAYERED;
        else exStyle &= ~(WS_EX_TRANSPARENT | WS_EX_LAYERED);
        SetWindowLong(m_hwnd, GWL_EXSTYLE, exStyle);
    }

    void SetTopMost(bool enabled) {
        if (!m_hwnd) return;
        SetWindowPos(m_hwnd, enabled ? HWND_TOPMOST : HWND_NOTOPMOST, 
                     0, 0, 0, 0, SWP_NOMOVE | SWP_NOSIZE);
    }

    void SetTargetWindow(HWND target) {
        m_targetWindow = target;
        UpdateWindowPosition();
    }

private:
    bool CreateWindow() {
        WNDCLASSEXW wc{};
        wc.cbSize = sizeof(WNDCLASSEXW);
        wc.style = CS_HREDRAW | CS_VREDRAW;
        wc.lpfnWndProc = StaticWndProc;
        wc.cbClsExtra = 0;
        wc.cbWndExtra = 0;
        wc.hInstance = GetModuleHandle(nullptr);
        wc.hCursor = LoadCursor(nullptr, IDC_ARROW);
        wc.hbrBackground = nullptr;
        wc.lpszClassName = m_config.windowClass.c_str();

        if (!RegisterClassExW(&wc)) return false;

        DWORD exStyle = WS_EX_LAYERED | WS_EX_TRANSPARENT | WS_EX_TOPMOST | WS_EX_NOACTIVATE;
        DWORD style = WS_POPUP;

        m_hwnd = CreateWindowExW(
            exStyle, m_config.windowClass.c_str(), m_config.windowTitle.c_str(),
            style, 0, 0, m_config.width, m_config.height,
            nullptr, nullptr, GetModuleHandle(nullptr), this
        );

        if (!m_hwnd) return false;

        // Make window click-through
        SetLayeredWindowAttributes(m_hwnd, 0, 255, LWA_ALPHA);

        ShowWindow(m_hwnd, SW_SHOW);
        UpdateWindow(m_hwnd);

        return true;
    }

    bool CreateRenderer() {
        m_renderer = CreateRenderer2D(m_config.backend);
        if (!m_renderer || !m_renderer->Initialize(m_hwnd, m_config.width, m_config.height)) {
            return false;
        }

        m_espDrawer = std::make_unique<ESPDrawer>(m_renderer.get());
        return true;
    }

    void RenderFrame() {
        auto now = std::chrono::high_resolution_clock::now();
        float deltaTime = std::chrono::duration<float>(now - m_lastTime).count();
        m_lastTime = now;

        UpdateWindowPosition();

        m_renderer->BeginFrame();

        if (m_renderCallback) {
            m_renderCallback(m_renderer.get(), m_espDrawer.get(), deltaTime);
        }

        // ImGui demo window (for testing)
        // ImGui::ShowDemoWindow();

        m_renderer->EndFrame();
    }

    void UpdateWindowPosition() {
        if (!m_targetWindow) return;

        RECT targetRect;
        if (GetWindowRect(m_targetWindow, &targetRect)) {
            int w = targetRect.right - targetRect.left;
            int h = targetRect.bottom - targetRect.top;

            if (w != m_config.width || h != m_config.height) {
                m_config.width = w;
                m_config.height = h;
                m_renderer->Resize(w, h);
                m_worldToScreen.screenWidth = w;
                m_worldToScreen.screenHeight = h;
            }

            SetWindowPos(m_hwnd, HWND_TOPMOST, 
                        targetRect.left, targetRect.top, w, h, SWP_NOACTIVATE);
        }
    }

    static LRESULT CALLBACK StaticWndProc(HWND hwnd, UINT msg, WPARAM wParam, LPARAM lParam) {
        OverlayManager* self = nullptr;
        if (msg == WM_NCCREATE) {
            self = static_cast<OverlayManager*>(((CREATESTRUCT*)lParam)->lpCreateParams);
            SetWindowLongPtr(hwnd, GWLP_USERDATA, (LONG_PTR)self);
        } else {
            self = (OverlayManager*)GetWindowLongPtr(hwnd, GWLP_USERDATA);
        }

        if (self) return self->WndProc(hwnd, msg, wParam, lParam);
        return DefWindowProc(hwnd, msg, wParam, lParam);
    }

    LRESULT WndProc(HWND hwnd, UINT msg, WPARAM wParam, LPARAM lParam) {
        if (ImGui_ImplWin32_WndProcHandler(hwnd, msg, wParam, lParam))
            return true;

        switch (msg) {
            case WM_DESTROY:
                m_running = false;
                PostQuitMessage(0);
                return 0;
            case WM_SIZE:
                if (m_renderer && wParam != SIZE_MINIMIZED) {
                    m_renderer->Resize(LOWORD(lParam), HIWORD(lParam));
                    m_worldToScreen.screenWidth = LOWORD(lParam);
                    m_worldToScreen.screenHeight = HIWORD(lParam);
                }
                return 0;
            case WM_KEYDOWN:
            case WM_KEYUP:
            case WM_MOUSEMOVE:
            case WM_LBUTTONDOWN:
            case WM_LBUTTONUP:
            case WM_RBUTTONDOWN:
            case WM_RBUTTONUP:
                if (m_inputCallback) m_inputCallback(wParam, lParam);
                break;
        }
        return DefWindowProc(hwnd, msg, wParam, lParam);
    }

    OverlayConfig m_config;
    HWND m_hwnd = nullptr;
    HWND m_targetWindow = nullptr;
    std::unique_ptr<Renderer2D> m_renderer;
    std::unique_ptr<ESPDrawer> m_espDrawer;
    WorldToScreen m_worldToScreen;
    RenderCallback m_renderCallback;
    InputCallback m_inputCallback;
    bool m_running = false;
    std::chrono::high_resolution_clock::time_point m_lastTime;
};
