### Usage Example (Legitimate Overlay Application)

```cpp
// main.cpp - Example: Performance Overlay / Debug Visualizer
#include "Overlay/OverlayManager.hpp"
#include "ESP/ESPDrawer.hpp"
#include "ESP/WorldToScreen.hpp"
#include <iostream>
#include <vector>
#include <random>

struct DebugEntity {
    Vec3 worldPos;
    Vec3 boundsMin, boundsMax;
    float health = 100.0f;
    float maxHealth = 100.0f;
    std::string name;
    Color color = Color::Green;
    std::vector<Vec3> skeletonJoints; // 3D joint positions
};

class DebugOverlayApp {
public:
    bool Initialize() {
        OverlayConfig config;
        config.width = 1920;
        config.height = 1080;
        config.windowTitle = "Debug Overlay";

        // Find target window (e.g., "Notepad", "Chrome", or your game)
        config.targetWindow = FindWindow(nullptr, L"Target Window Title");

        return m_overlay.Initialize(config, [this](Renderer2D* renderer, ESPDrawer* esp, float dt) {
            RenderFrame(renderer, esp, dt);
        });
    }

    void Run() {
        m_overlay.Run();
    }

private:
    void RenderFrame(Renderer2D* renderer, ESPDrawer* esp, float deltaTime) {
        // Update world-to-screen matrices (in real app, get from target process)
        UpdateViewProjection();

        // Clear with transparent
        // (handled by renderer BeginFrame)

        // Draw debug entities
        for (auto& entity : m_entities) {
            DrawEntity(esp, entity);
        }

        // Draw UI
        DrawUI(renderer);

        // Update animation
        UpdateEntities(deltaTime);
    }

    void DrawEntity(ESPDrawer* esp, const DebugEntity& entity) {
        // Project 3D bounds to 2D box
        if (auto box = m_w2s.CalculateBounds(entity.boundsMin, entity.boundsMax)) {
            // Distance-based scaling
            float dist = m_w2s.GetDistance(entity.worldPos, m_cameraPos);
            esp->DrawDistanceScaledBox(*box, dist, 100.0f);

            // Health bar above box
            HealthBar healthBar;
            healthBar.position = Vec2(box->min.x, box->min.y - 10);
            healthBar.size = Vec2(box->Width(), 5);
            healthBar.healthPercent = entity.health / entity.maxHealth;
            healthBar.rounding = 2.0f;
            esp->DrawHealthBar(healthBar);

            // Name text
            ESPText nameText;
            nameText.position = Vec2(box->Center().x, box->min.y - 20);
            nameText.text = entity.name;
            nameText.color = entity.color;
            nameText.fontSize = 12.0f;
            nameText.centered = true;
            nameText.outline = true;
            esp->DrawText(nameText);

            // Distance text
            char distBuf[32];
            snprintf(distBuf, sizeof(distBuf), "%.1fm", dist);
            ESPText distText;
            distText.position = Vec2(box->Center().x, box->max.y + 5);
            distText.text = distBuf;
            distText.color = Color::White;
            distText.fontSize = 10.0f;
            distText.centered = true;
            distText.outline = true;
            esp->DrawText(distText);
        }

        // Project and draw skeleton
        if (!entity.skeletonJoints.empty()) {
            std::vector<Vec2> screenJoints;
            screenJoints.reserve(entity.skeletonJoints.size());

            for (const auto& joint3D : entity.skeletonJoints) {
                if (auto screenPos = m_w2s.Project(joint3D)) {
                    screenJoints.push_back(*screenPos);
                } else {
                    screenJoints.push_back(Vec2(0, 0)); // Invalid
                }
            }

            esp->DrawSkeletonFromJoints(screenJoints, Skeleton::StandardConnections, 
                                       entity.color, 2.0f);
        }

        // Snapline from screen center
        Snapline snap;
        snap.from = m_w2s.GetScreenCenter();
        if (auto targetPos = m_w2s.Project(entity.worldPos)) {
            snap.to = *targetPos;
            snap.color = entity.color;
            snap.thickness = 1.0f;
            snap.dashed = true;
            esp->DrawSnapline(snap);
        }
    }

    void DrawUI(Renderer2D* renderer) {
        ImGui::Begin("Debug Overlay Controls", nullptr, ImGuiWindowFlags_AlwaysAutoResize);

        ImGui::Text("Entities: %zu", m_entities.size());
        ImGui::Text("FPS: %.1f", ImGui::GetIO().Framerate);
        ImGui::Separator();

        if (ImGui::Button("Add Random Entity")) {
            AddRandomEntity();
        }
        ImGui::SameLine();
        if (ImGui::Button("Clear All")) {
            m_entities.clear();
        }

        ImGui::Separator();
        ImGui::SliderFloat("Camera X", &m_cameraPos.x, -50, 50);
        ImGui::SliderFloat("Camera Y", &m_cameraPos.y, -50, 50);
        ImGui::SliderFloat("Camera Z", &m_cameraPos.z, -50, 50);

        ImGui::End();
    }

    void UpdateViewProjection() {
        // Simple camera setup
        // View matrix: look at origin from camera position
        Vec3 forward = (Vec3(0, 0, 0) - m_cameraPos).Normalized();
        Vec3 right = Vec3(0, 1, 0).Cross(forward).Normalized();
        Vec3 up = forward.Cross(right);

        m_w2s.viewMatrix = Matrix4x4::Identity();
        m_w2s.viewMatrix.m[0][0] = right.x;   m_w2s.viewMatrix.m[0][1] = up.x;     m_w2s.viewMatrix.m[0][2] = -forward.x; m_w2s.viewMatrix.m[0][3] = 0;
        m_w2s.viewMatrix.m[1][0] = right.y;   m_w2s.viewMatrix.m[1][1] = up.y;     m_w2s.viewMatrix.m[1][2] = -forward.y; m_w2s.viewMatrix.m[1][3] = 0;
        m_w2s.viewMatrix.m[2][0] = right.z;   m_w2s.viewMatrix.m[2][1] = up.z;     m_w2s.viewMatrix.m[2][2] = -forward.z; m_w2s.viewMatrix.m[2][3] = 0;
        m_w2s.viewMatrix.m[3][0] = -right.Dot(m_cameraPos);
        m_w2s.viewMatrix.m[3][1] = -up.Dot(m_cameraPos);
        m_w2s.viewMatrix.m[3][2] = forward.Dot(m_cameraPos);
        m_w2s.viewMatrix.m[3][3] = 1.0f;

        // Perspective projection
        float fov = 90.0f * 3.14159f / 180.0f;
        float aspect = (float)m_w2s.screenWidth / m_w2s.screenHeight;
        float near = 0.1f, far = 1000.0f;
        float f = 1.0f / std::tan(fov * 0.5f);

        m_w2s.projectionMatrix = Matrix4x4::Identity();
        m_w2s.projectionMatrix.m[0][0] = f / aspect;
        m_w2s.projectionMatrix.m[1][1] = f;
        m_w2s.projectionMatrix.m[2][2] = far / (near - far);
        m_w2s.projectionMatrix.m[2][3] = -1.0f;
        m_w2s.projectionMatrix.m[3][2] = near * far / (near - far);
        m_w2s.projectionMatrix.m[3][3] = 0.0f;
    }

    void UpdateEntities(float dt) {
        for (auto& entity : m_entities) {
            // Animate
            entity.worldPos.x += std::sin(m_time * 2.0f + entity.worldPos.z) * 0.5f * dt;
            entity.worldPos.z += std::cos(m_time * 1.5f + entity.worldPos.x) * 0.3f * dt;

            // Update bounds
            Vec3 halfSize(1.0f, 1.8f, 1.0f);
            entity.boundsMin = entity.worldPos - halfSize;
            entity.boundsMax = entity.worldPos + halfSize;

            // Animate health
            entity.health = 50.0f + 50.0f * std::sin(m_time + entity.worldPos.x);
        }
        m_time += dt;
    }

    void AddRandomEntity() {
        static std::mt19937 rng(std::random_device{}());
        static std::uniform_real_distribution<float> posDist(-20, 20);
        static std::uniform_real_distribution<float> healthDist(20, 100);
        static std::uniform_int_distribution<int> colorDist(0, 360);

        DebugEntity entity;
        entity.worldPos = Vec3(posDist(rng), 0, posDist(rng));
        entity.health = healthDist(rng);
        entity.maxHealth = 100.0f;
        entity.name = "Entity_" + std::to_string(m_entities.size());
        entity.color = Color::FromHSV(colorDist(rng), 0.8f, 0.9f);

        // Generate skeleton joints (17 COCO keypoints)
        entity.skeletonJoints.resize(17);
        for (int i = 0; i < 17; ++i) {
            entity.skeletonJoints[i] = entity.worldPos + Vec3(
                (rng() % 100 - 50) * 0.05f,
                (rng() % 100 - 50) * 0.05f + 1.0f,
                (rng() % 100 - 50) * 0.05f
            );
        }

        m_entities.push_back(entity);
    }

    OverlayManager m_overlay;
    WorldToScreen m_w2s;
    Vec3 m_cameraPos = {0, 5, -15};
    std::vector<DebugEntity> m_entities;
    float m_time = 0.0f;
};

int main() {
    DebugOverlayApp app;
    if (!app.Initialize()) {
        std::cerr << "Failed to initialize overlay\n";
        return 1;
    }

    app.Run();
    return 0;
}
