## 3. Configuration (`internal/infra/config.go`)

```go
package infra

import (
	"fmt"
	"os"
	"time"

	"github.com/joho/godotenv"
)

// Config holds all runtime configuration.
type Config struct {
	Server   ServerConfig
	Postgres PostgresConfig
	Redis    RedisConfig
	Kafka    KafkaConfig
	Metrics  MetricsConfig
}

// ServerConfig – HTTP server settings.
type ServerConfig struct {
	Addr         string        // e.g. ":8080"
	ReadTimeout  time.Duration
	WriteTimeout time.Duration
	IdleTimeout  time.Duration
}

// PostgresConfig – DSN and pool settings.
type PostgresConfig struct {
	DSN          string
	MaxOpenConns int
	MaxIdleConns int
	ConnMaxLifetime time.Duration
}

// RedisConfig – connection details.
type RedisConfig struct {
	Addr     string
	Password string
	DB       int
	PoolSize int
	MinIdleConns int
}

// KafkaConfig – producer settings.
type KafkaConfig struct {
	Brokers []string
	Topic   string
	// Optional: SASL, TLS, etc.
}

// MetricsConfig – Prometheus endpoint.
type MetricsConfig struct {
	Enable bool
	Path   string // e.g. "/metrics"
}

// Load reads from environment (and optionally a .env file) and returns a populated Config.
func Load() (*Config, error) {
	// Try to load .env (ignore error if file not present – useful in prod where env is injected)
	_ = godotenv.Load() // nolint:errcheck

	cfg := &Config{}

	// ----- Server -----
	cfg.Server.Addr = getEnv("SERVER_ADDR", ":8080")
	cfg.Server.ReadTimeout = durationEnv("SERVER_READ_TIMEOUT", 5*time.Second)
	cfg.Server.WriteTimeout = durationEnv("SERVER_WRITE_TIMEOUT", 10*time.Second)
	cfg.Server.IdleTimeout = durationEnv("SERVER_IDLE_TIMEOUT", 60*time.Second)

	// ----- Postgres -----
	cfg.Postgres.DSN = getEnv("POSTGRES_DSN", "postgres://user:pass@localhost:5432/db?sslmode=disable")
	cfg.Postgres.MaxOpenConns = intEnv("POSTGRES_MAX_OPEN_CONNS", 25)
	cfg.Postgres.MaxIdleConns = intEnv("POSTGRES_MAX_IDLE_CONNS", 25)
	cfg.Postgres.ConnMaxLifetime = durationEnv("POSTGRES_CONN_MAX_LIFETIME", 30*time.Minute)

	// ----- Redis -----
	cfg.Redis.Addr = getEnv("REDIS_ADDR", "localhost:6379")
	cfg.Redis.Password = getEnv("REDIS_PASSWORD", "")
	cfg.Redis.DB = intEnv("REDIS_DB", 0)
	cfg.Redis.PoolSize = intEnv("REDIS_POOL_SIZE", 10)
	cfg.Redis.MinIdleConns = intEnv("REDIS_MIN_IDLE_CONNS", 2)

	// ----- Kafka -----
	brokersStr := getEnv("KAFKA_BROKERS", "localhost:9092")
	cfg.Kafka.Brokers = splitAndTrim(brokersStr, ",")
	cfg.Kafka.Topic = getEnv("KAFKA_TOPIC", "events")

	// ----- Metrics -----
	cfg.Metrics.Enable = getEnv("METRICS_ENABLE", "true") == "true"
	cfg.Metrics.Path = getEnv("METRICS_PATH", "/metrics")

	return cfg, nil
}

// Helper functions ---------------------------------------------------------

func getEnv(key, fallback string) string {
	if v := os.Getenv(key); v != "" {
		return v
	}
	return fallback
}

func intEnv(key string, fallback int) int {
	if v := os.Getenv(key); v != "" {
		var i int
		fmt.Sscanf(v, "%d", &i)
		if i > 0 {
			return i
		}
	}
	return fallback
}

func durationEnv(key string, fallback time.Duration) time.Duration {
	if v := os.Getenv(key); v != "" {
		if d, err := time.ParseDuration(v); err == nil {
			return d
		}
	}
	return fallback
}

func splitAndTrim(s, sep string) []string {
	if s == "" {
		return nil
	}
	parts := make([]string, 0)
	for _, p := range strings.Split(s, sep) {
		if v := strings.TrimSpace(p); v != "" {
			parts = append(parts, v)
		}
	}
	return parts
}
```

> **Note:** The config struct is deliberately *immutable* after construction – no setters – to avoid accidental mutation at runtime.

