package domain

import (
	"time"
)

// Order represents a business entity (example).
type Order struct {
	ID        string    `json:"id"`
	UserID    string    `json:"user_id"`
	Amount    float64   `json:"amount"`
	Status    Status    `json:"status"`
	CreatedAt time.Time `json:"created_at"`
	UpdatedAt time.Time `json:"updated_at"`
}

// Status is a simple enum – could be iota or string.
type Status string

const (
	StatusPending   Status = "pending"
	StatusPaid      Status = "paid"
	StatusCancelled Status = "cancelled"
)

// OrderRepository defines the persistence port.
type OrderRepository interface {
	Create(ctx context.Context, o *Order) error
	GetByID(ctx context.Context, id string) (*Order, error)
	Update(ctx context.Context, o *Order) error
}

// OrderCache defines the cache‑aside port.
type OrderCache interface {
	Get(ctx context.Context, id string) (*Order, error)
	Set(ctx context.Context, o *Order) error
	Delete(ctx context.Context, id string) error
}

// OrderEventPublisher defines the outgoing event port.
type OrderEventPublisher interface {
	PublishOrderCreated(ctx context.Context, o *Order) error
	PublishOrderUpdated(ctx context.Context, o *Order) error
}
```

> **Why interfaces?** The use‑case layer depends only on these contracts; concrete implementations live in `infra`.

