## 5. Application / Use‑Case Layer (`internal/app/service.go`)

```go
package app

import (
	"context"
	"time"

	"github.com/yourorg/microservice/internal/domain"
	"github.com/pkg/errors"
)

// OrderService encapsulates all business rules for Order.
type OrderService struct {
	repo      domain.OrderRepository
	cache     domain.OrderCache
	publisher domain.OrderEventPublisher
}

// NewOrderService is the constructor used by the composition root.
func NewOrderService(r domain.OrderRepository, c domain.OrderCache, p domain.OrderEventPublisher) *OrderService {
	return &OrderService{
		repo:      r,
		cache:     c,
		publisher: p,
	}
}

// CreateOrder validates, persists, caches and publishes an event.
func (s *OrderService) CreateOrder(ctx context.Context, userID string, amount float64) (*domain.Order, error) {
	if userID == "" {
		return nil, errors.New("user_id is required")
	}
	if amount <= 0 {
		return nil, errors.New("amount must be > 0")
	}

	now := time.Now().UTC()
	o := &domain.Order{
		ID:        generateID(), // simple UUIDv4 placeholder
		UserID:    userID,
		Amount:    amount,
		Status:    domain.StatusPending,
		CreatedAt: now,
		UpdatedAt: now,
	}

	// Persist
	if err := s.repo.Create(ctx, o); err != nil {
		return nil, errors.Wrap(err, "failed to create order")
	}

	// Cache‑aside: write-through
	if err := s.cache.Set(ctx, o); err != nil {
		// Log but do not fail the request – cache is best‑effort
		// In a real service you would use a logger here.
		_ = err
	}

	// Publish domain event
	if err := s.publisher.PublishOrderCreated(ctx, o); err != nil {
		// Again, log and continue – eventual consistency
		_ = err
	}

	return o, nil
}

// GetOrder implements read‑through cache‑aside.
func (s *OrderService) GetOrder(ctx context.Context, id string) (*domain.Order, error) {
	if id == "" {
		return nil, errors.New("order id required")
	}

	// Try cache first
	if o, err := s.cache.Get(ctx, id); err == nil {
		return o, nil
	}
	// Cache miss → DB
	o, err := s.repo.GetByID(ctx, id)
	if err != nil {
		return nil, errors.Wrap(err, "failed to fetch order")
	}
	// Populate cache for next request (write‑through)
	if err := s.cache.Set(ctx, o); err != nil {
		_ = err // best‑effort
	}
	return o, nil
}

// UpdateOrderStatus demonstrates a command that updates state and publishes.
func (s *OrderService) UpdateOrderStatus(ctx context.Context, id string, status domain.Status) (*domain.Order, error) {
	o, err := s.GetOrder(ctx, id)
	if err != nil {
		return nil, err
	}
	if o.Status == status {
		return o, nil // idempotent
	}
	o.Status = status
	o.UpdatedAt = time.Now().UTC()

	if err := s.repo.Update(ctx, o); err != nil {
		return nil, errors.Wrap(err, "failed to update order")
	}
	if err := s.cache.Set(ctx, o); err != nil {
		_ = err
	}
	if err := s.publisher.PublishOrderUpdated(ctx, o); err != nil {
		_ = err
	}
	return o, nil
}

// Simple UUIDv4 generator – replace with a proper library (e.g. github.com/google/uuid) in prod.
func generateID() string {
	// placeholder
	return "00000000-0000-0000-0000-000000000000"
}
```

> The service is **pure Go** – no HTTP, no DB, no Kafka imports. This makes it trivial to unit‑test with mocks.

