### 6.1 PostgreSQL repository (`postgres.go`)

```go
package infra

import (
	"context"
	"database/sql"
	"fmt"
	"time"

	"github.com/jackc/pgx/v5/stdlib"
	"github.com/yourorg/microservice/internal/domain"
	"github.com/pkg/errors"
)

// pgOrderRepo implements domain.OrderRepository using pgx.
type pgOrderRepo struct {
	db *sql.DB
}

// NewPostgresOrderRepo builds a repository with a connection pool.
func NewPostgresOrderRepo(cfg PostgresConfig) (domain.OrderRepository, error) {
	db, err := sql.Open("pgx", cfg.DSN)
	if err != nil {
		return nil, errors.Wrap(err, "failed to open postgres")
	}
	db.SetMaxOpenConns(cfg.MaxOpenConns)
	db.SetMaxIdleConns(cfg.MaxIdleConns)
	db.SetConnMaxLifetime(cfg.ConnMaxLifetime)

	// Verify connection
	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()
	if err := db.PingContext(ctx); err != nil {
		_ = db.Close()
		return nil, errors.Wrap(err, "failed to ping postgres")
	}
	return &pgOrderRepo{db: db}, nil
}

func (r *pgOrderRepo) Create(ctx context.Context, o *domain.Order) error {
	const query = `
		INSERT INTO orders (id, user_id, amount, status, created_at, updated_at)
		VALUES ($1, $2, $3, $4, $5, $6)
	`
	_, err := r.db.ExecContext(ctx, query,
		o.ID, o.UserID, o.Amount, o.Status, o.CreatedAt, o.UpdatedAt)
	return errors.Wrap(err, "insert failed")
}

func (r *pgOrderRepo) GetByID(ctx context.Context, id string) (*domain.Order, error) {
	const query = `
		SELECT id, user_id, amount, status, created_at, updated_at
		FROM orders
		WHERE id = $1
	`
	var o domain.Order
	err := r.db.QueryRowContext(ctx, query, id).Scan(
		&o.ID, &o.UserID, &o.Amount, &o.Status, &o.CreatedAt, &o.UpdatedAt)
	if err == sql.ErrNoRows {
		return nil, domain.ErrNotFound // define in domain if needed
	}
	if err != nil {
		return nil, errors.Wrap(err, "select failed")
	}
	return &o, nil
}

func (r *pgOrderRepo) Update(ctx context.Context, o *domain.Order) error {
	const query = `
		UPDATE orders
		SET user_id = $1, amount = $2, status = $3, updated_at = $4
		WHERE id = $5
	`
	_, err := r.db.ExecContext(ctx, query,
		o.UserID, o.Amount, o.Status, o.UpdatedAt, o.ID)
	return errors.Wrap(err, "update failed")
}
```

