### 6.2 Redis cache‑aside (`redis.go`)

```go
package infra

import (
	"context"
	"encoding/json"
	"time"

	"github.com/redis/go-redis/v9"
	"github.com/yourorg/microservice/internal/domain"
	"github.com/pkg/errors"
)

// redisCache implements domain.OrderCache using Redis.
type redisCache struct {
	client *redis.Client
	ttl    time.Duration // how long to keep cached entries
}

// NewRedisCache builds a cache client.
func NewRedisCache(cfg RedisConfig) (domain.OrderCache, error) {
	rdb := redis.NewClient(&redis.Options{
		Addr:     cfg.Addr,
		Password: cfg.Password, // empty if no auth
		DB:       cfg.DB,
		PoolSize: cfg.PoolSize,
		MinIdleConns: cfg.MinIdleConns,
	})

	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()
	if err := rdb.Ping(ctx).Err(); err != nil {
		return nil, errors.Wrap(err, "failed to ping redis")
	}
	return &redisCache{
		client: rdb,
		ttl:    10 * time.Minute, // configurable via cfg if desired
	}, nil
}

func (c *redisCache) Get(ctx context.Context, id string) (*domain.Order, error) {
	key := orderKey(id)
	data, err := c.client.Get(ctx, key).Result()
	if err == redis.Nil {
		return nil, domain.ErrNotFound
	}
	if err != nil {
		return nil, errors.Wrap(err, "redis get failed")
	}
	var o domain.Order
	if err := json.Unmarshal([]byte(data), &o); err != nil {
		return nil, errors.Wrap(err, "failed to unmarshal order from cache")
	}
	return &o, nil
}

func (c *redisCache) Set(ctx context.Context, o *domain.Order) error {
	key := orderKey(o.ID)
	b, err := json.Marshal(o)
	if err != nil {
		return errors.Wrap(err, "failed to marshal order")
	}
	if err := c.client.Set(ctx, key, b, c.ttl).Err(); err != nil {
		return errors.Wrap(err, "redis set failed")
	}
	return nil
}

func (c *redisCache) Delete(ctx context.Context, id string) error {
	key := orderKey(id)
	if err := c.client.Del(ctx, key).Err(); err != nil {
		return errors.Wrap(err, "redis del failed")
	}
	return nil
}

func orderKey(id string) string {
	return "order:" + id
}
```

### 6.3 Kafka event publisher (`kafka.go`)

```go
package infra

import (
	"context"
	"encoding/json"
	"time"

	"github.com/segmentio/kafka-go"
	"github.com/yourorg/microservice/internal/domain"
	"github.com/pkg/errors"
)

// kafkaPublisher implements domain.OrderEventPublisher.
type kafkaPublisher struct {
	w   *kafka.Writer
	topic string
}

// NewKafkaPublisher builds a Kafka writer.
func NewKafkaPublisher(cfg KafkaConfig) (domain.OrderEventPublisher, error) {
	if len(cfg.Brokers) == 0 {
		return nil, errors.New("kafka brokers list empty")
	}
	w := &kafka.Writer{
		Addr:     kafka.TCP(cfg.Brokers...),
		Topic:    cfg.Kafka.Topic,
		Balancer: &kafka.LeastBytes{},
		// Optional: required acks, compression, etc.
		// Timeout: 10 * time.Second,
	}
	return &kafkaPublisher{w: w, topic: cfg.Kafka.Topic}, nil
}

// PublishOrderCreated sends a JSON‑encoded OrderCreated event.
func (p *kafkaPublisher) PublishOrderCreated(ctx context.Context, o *domain.Order) error {
	return p.publish(ctx, map[string]interface{}{
		"event_type": "OrderCreated",
		"order_id":   o.ID,
		"user_id":    o.UserID,
		"amount":     o.Amount,
		"status":     string(o.Status),
		"timestamp":  time.Now().UTC().Format(time.RFC3339Nano),
	})
}

// PublishOrderUpdated sends an OrderUpdated event.
func (p *kafkaPublisher) PublishOrderUpdated(ctx context.Context, o *domain.Order) error {
	return p.publish(ctx, map[string]interface{}{
		"event_type": "OrderUpdated",
		"order_id":   o.ID,
		"user_id":    o.UserID,
		"amount":     o.Amount,
		"status":     string(o.Status),
		"timestamp":  time.Now().UTC().Format(time.RFC3339Nano),
	})
}

func (p *kafkaPublisher) publish(ctx context.Context, msg map[string]interface{}) error {
	b, err := json.Marshal(msg)
	if err != nil {
		return errors.Wrap(err, "failed to marshal kafka message")
	}
	if err := p.w.WriteMessages(ctx, kafka.Message{
		Key:   []byte(msg["order_id"].(string)), // key for partitioning
		Value: b,
	}); err != nil {
		return errors.Wrap(err, "kafka write failed")
	}
	return nil
}

// Close releases underlying resources (call during graceful shutdown).
func (p *kafkaPublisher) Close() error {
	return p.w.Close()
}
```

### 6.4 Prometheus metrics (`metrics.go`)

```go
package infra

import (
	"net/http"

	"github.com/prometheus/client_golang/prometheus"
	"github.com/prometheus/client_golang/prometheus/promhttp"
	"go.uber.org/zap"
)

// Metrics holds prometheus collectors used across the service.
type Metrics struct {
	HTTPRequestsTotal *prometheus.CounterVec
	HTTPRequestLatency *prometheus.HistogramVec
	DBQueryTotal      *prometheus.CounterVec
	CacheHitTotal     *prometheus.Counter
	CacheMissTotal    *prometheus.Counter
	KafkaPublishTotal *prometheus.CounterVec
}

// NewMetrics registers and returns a Metrics struct.
func NewMetrics() *Metrics {
	m := &Metrics{
		HTTPRequestsTotal: prometheus.NewCounterVec(
			prometheus.CounterOpts{
				Name: "http_requests_total",
				Help: "Total number of HTTP requests",
			},
			[]string{"method", "path", "status"},
		),
		HTTPRequestLatency: prometheus.NewHistogramVec(
			prometheus.HistogramOpts{
				Name:    "http_request_duration_seconds",
				Help:    "Latency of HTTP requests",
				Buckets: prometheus.ExponentialBuckets(0.001, 2, 10), // 1ms ~ 1s
			},
			[]string{"method", "path"},
		),
		DBQueryTotal: prometheus.NewCounterVec(
			prometheus.CounterOpts{
				Name: "db_query_total",
				Help: "Number of DB queries executed",
			},
			[]string{"operation", "success"},
		),
		CacheHitTotal: prometheus.NewCounter(
			prometheus.CounterOpts{
				Name: "cache_hit_total",
				Help: "Number of cache hits",
			},
		),
		CacheMissTotal: prometheus.NewCounter(
			prometheus.CounterOpts{
				Name: "cache_miss_total",
				Help: "Number of cache misses",
			},
		),
		KafkaPublishTotal: prometheus.NewCounterVec(
			prometheus.CounterOpts{
				Name: "kafka_publish_total",
				Help: "Number of messages published to Kafka",
			},
			[]string{"topic", "success"},
		),
	}

	// Register all collectors
	prometheus.MustRegister(m.HTTPRequestsTotal)
	prometheus.MustRegister(m.HTTPRequestLatency)
	prometheus.MustRegister(m.DBQueryTotal)
	prometheus.MustRegister(m.CacheHitTotal)
	prometheus.MustRegister(m.CacheMissTotal)
	prometheus.MustRegister(m.KafkaPublishTotal)

	return m
}

// Handler returns an http.Handler that serves /metrics.
func (m *Metrics) Handler() http.Handler {
	return promhttp.Handler()
}

// Example middleware wrappers (to be used in transport layer)
func (m *Metrics) HTTPMiddleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		timer := prometheus.NewTimer(m.HTTPRequestLatency.WithLabelValues(r.Method, r.URL.Path))
		ww := &responseWriter{ResponseWriter: w, status: 200}
		next.ServeHTTP(ww, r)
		timer.ObserveDuration()
		m.HTTPRequestsTotal.WithLabelValues(r.Method, r.URL.Path, string(rune(ww.status))).Inc()
	})
}

type responseWriter struct {
	http.ResponseWriter
	status int
}

func (rw *responseWriter) WriteHeader(code int) {
	rw.status = code
	rw.ResponseWriter.WriteHeader(code)
}
```

> **Usage** – In the HTTP transport layer we wrap the handler with `metrics.HTTPMiddleware`. DB and cache calls should increment the respective counters (shown later in the repository adapters for brevity).

