## 7. HTTP Transport (`internal/transport/http`)

### 7.1 handler.go

```go
package http

import (
	"context"
	"encoding/json"
	"net/http"
	"time"

	"github.com/gin-gonic/gin"
	"github.com/go-playground/validator/v10"
	"github.com/yourorg/microservice/internal/app"
	"github.com/yourorg/microservice/internal/domain"
	"go.uber.org/zap"
)

// OrderHandler couples gin with the application service.
type OrderHandler struct {
	service *app.OrderService
	logger  *zap.Logger
	validate *validator.Validate
	metrics *infra.Metrics // optional: for custom metrics not covered by middleware
}

// NewOrderHandler builds the handler.
func NewOrderHandler(svc *app.OrderService, logger *zap.Logger) *OrderHandler {
	return &OrderHandler{
		service: svc,
		logger:  logger,
		validate: validator.New(),
	}
}

// CreateOrder godoc
// @Summary Create a new order
// @Description Creates an order, persists it, caches it and publishes a Kafka event.
// @Tags orders
// @Accept json
// @Produce json
// @Param order body createOrderRequest true "Order payload"
// @Success 201 {object} orderResponse
// @Failure 400 {object} errorResponse
// @Failure 500 {object} errorResponse
// @Router /orders [post]
func (h *OrderHandler) CreateOrder(c *gin.Context) {
	var req createOrderRequest
	if err := c.ShouldBindJSON(&req); err != nil {
		h.logger.Warn("invalid request", zap.Error(err))
		c.JSON(http.StatusBadRequest, errorResponse{Message: "invalid request"})
		return
	}
	if err := h.validate.Struct(req); err != nil {
		h.logger.Warn("validation failed", zap.Error(err))
		c.JSON(http.StatusBadRequest, errorResponse{Message: validationError(err)})
		return
	}

	ctx := c.Request.Context()
	o, err := h.service.CreateOrder(ctx, req.UserID, req.Amount)
	if err != nil {
		h.logger.Error("failed to create order", zap.Error(err))
		c.JSON(http.StatusInternalServerError, errorResponse{Message: "internal error"})
		return
	}
	c.JSON(http.StatusCreated, orderResponse{Order: o})
}

// GetOrder godoc
// @Summary Retrieve an order by ID
// @Tags orders
// @Accept json
// @Produce json
// @Param id path string true "Order ID"
// @Success 200 {object} orderResponse
// @Failure 404 {object} errorResponse
// @Failure 500 {object} errorResponse
// @Router /orders/{id} [get]
func (h *OrderHandler) GetOrder(c *gin.Context) {
	id := c.Param("id")
	if id == "" {
		c.JSON(http.StatusBadRequest, errorResponse{Message: "missing order id"})
		return
	}
	ctx := c.Request.Context()
	o, err := h.service.GetOrder(ctx, id)
	if err != nil {
		if errors.Is(err, domain.ErrNotFound) {
			c.JSON(http.StatusNotFound, errorResponse{Message: "order not found"})
			return
		}
		h.logger.Error("failed to get order", zap.Error(err))
		c.JSON(http.StatusInternalServerError, errorResponse{Message: "internal error"})
		return
	}
	c.JSON(http.StatusOK, orderResponse{Order: o})
}

// UpdateStatus godoc
// @Summary Update order status
// @Tags orders
// @Accept json
// @Produce json
// @Param id path string true "Order ID"
// @Param status body updateStatusRequest true "New status"
// @Success 200 {object} orderResponse
// @Failure 400 {object} errorResponse
// @Failure 404 {object} errorResponse
// @Failure 500 {object} errorResponse
// @Router /orders/{id}/status [patch]
func (h *OrderHandler) UpdateStatus(c *gin.Context) {
	id := c.Param("id")
	if id == "" {
		c.JSON(http.StatusBadRequest, errorResponse{Message: "missing order id"})
		return
	}
	var req updateStatusRequest
	if err := c.ShouldBindJSON(&req); err != nil {
		h.logger.Warn("invalid request", zap.Error(err))
		c.JSON(http.StatusBadRequest, errorResponse{Message: "invalid request"})
		return
	}
	if err := h.validate.Struct(req); err != nil {
		h.logger.Warn("validation failed", zap.Error(err))
		c.JSON(http.StatusBadRequest, errorResponse{Message: validationError(err)})
		return
	}
	ctx := c.Request.Context()
	o, err := h.service.UpdateOrderStatus(ctx, id, req.Status)
	if err != nil {
		if errors.Is(err, domain.ErrNotFound) {
			c.JSON(http.StatusNotFound, errorResponse{Message: "order not found"})
			return
		}
		h.logger.Error("failed to update order", zap.Error(err))
		c.JSON(http.StatusInternalServerError, errorResponse{Message: "internal error"})
		return
	}
	c.JSON(http.StatusOK, orderResponse{Order: o})
}

/* ---------- DTOs ---------- */

type createOrderRequest struct {
	UserID string  `json:"user_id" validate:"required,uuid"` // adjust validation as needed
	Amount float64 `json:"amount" validate:"required,gt=0"`
}

type updateStatusRequest struct {
	Status domain.Status `json:"status" validate:"required,oneof=pending paid cancelled"`
}

type orderResponse struct {
	Order *domain.Order `json:"order"`
}

type errorResponse struct {
	Message string `json:"error"`
}

// validationError returns the first validation error message.
func validationError(err error) string {
	if verr, ok := err.(validator.ValidationErrors); ok && len(verr) > 0 {
		return verr[0].Error()
	}
	return err.Error()
}
