### 7.2 router.go (middleware, metrics, logging)

```go
package http

import (
	"net/http"
	"time"

	"github.com/gin-gonic/gin"
	"github.com/yourorg/microservice/internal/infra"
	"go.uber.org/zap"
)

// NewRouter builds a gin.Engine with all middlewares mounted.
func NewRouter(
	h *OrderHandler,
	logger *zap.Logger,
	metrics *infra.Metrics,
) *gin.Engine {
	r := gin.New()

	// Recovery + Logger (zap via gin's built-in logger replaced with zap)
	r.Use(gin.Recovery())
	r.Use(zapLogger(logger))
	r.Use(metrics.HTTPMiddleware) // Prometheus middleware

	// Health endpoint
	r.GET("/healthz", func(c *gin.Context) { c.Status(http.StatusOK) })

	// Prometheus endpoint (exposes /metrics)
	r.GET("/metrics", gin.WrapH(metrics.Handler()))

	// API versioning (optional)
	v1 := r.Group("/api/v1")
	{
		orders := v1.Group("/orders")
		{
			orders.POST("", h.CreateOrder)
			orders.GET("/:id", h.GetOrder)
			orders.PATCH("/:id/status", h.UpdateStatus)
		}
	}

	return r
}

// zapLogger is a gin middleware that writes structured logs via zap.
func zapLogger(logger *zap.Logger) gin.HandlerFunc {
	return func(c *gin.Context) {
		start := time.Now()
		path := c.Request.URL.Path
		raw := c.Request.URL.RawQuery

		// Process request
		c.Next()

		// Log only when path is not a health check (optional)
		if path != "/healthz" && path != "/metrics" {
			end := time.Now()
			latency := end.Sub(start)

			logger.Info("http request",
				zap.String("method", c.Request.Method),
				zap.String("path", path),
				zap.String("query", raw),
				zap.Int("status", c.Writer.Status()),
				zap.Duration("latency", latency),
				zap.String("client_ip", c.ClientIP()),
				zap.String("user_agent", c.Request.UserAgent()),
			)
		}
	}
}
