## 8. Composition Root (`cmd/server/main.go`)

```go
package main

import (
	"context"
	"log"
	"net/http"
	"os"
	"os/signal"
	"time"

	"github.com/yourorg/microservice/internal/app"
	"github.com/yourorg/microservice/internal/domain"
	"github.com/yourorg/microservice/internal/infra"
	"github.com/yourorg/microservice/internal/transport/http"
	"go.uber.org/zap"
)

func main() {
	// ---------- Logger ----------
	logger, err := zap.NewProduction()
	if err != nil {
		log.Fatalf("cannot initialize zap: %v", err)
	}
	defer logger.Sync() // flushes buffer, if any

	// ---------- Configuration ----------
	cfg, err := infra.Load()
	if err != nil {
		logger.Fatal("failed to load config", zap.Error(err))
	}
	logger.Info("configuration loaded", zap.Any("config", cfg))

	// ---------- Metrics ----------
	metrics := infra.NewMetrics()

	// ---------- PostgreSQL ----------
	pgRepo, err := infra.NewPostgresOrderRepo(cfg.Postgres)
	if err != nil {
		logger.Fatal("failed to init postgres repo", zap.Error(err))
	}
	defer pgRepo.(*infra.pgOrderRepo).db.Close() // nolint:errcheck

	// ---------- Redis ----------
	redisCache, err := infra.NewRedisCache(cfg.Redis)
	if err != nil {
		logger.Fatal("failed to init redis cache", zap.Error(err))
	}
	defer redisCache.(*infra.redisCache).client.Close() // nolint:errcheck

	// ---------- Kafka ----------
	kafkaPub, err := infra.NewKafkaPublisher(cfg.Kafka)
	if err != nil {
		logger.Fatal("failed to init kafka publisher", zap.Error(err))
	}
	// Ensure we close the writer on shutdown
	defer func() {
		if err := kafkaPub.(*infra.kafkaPublisher).Close(); err != nil {
			logger.Error("error closing kafka writer", zap.Error(err))
		}
	}()

	// ---------- Application Service ----------
	orderSvc := app.NewOrderService(pgRepo, redisCache, kafkaPub)

	// ---------- HTTP Handler ----------
	handler := http.NewOrderHandler(orderSvc, logger)

	// ---------- Router ----------
	router := http.NewRouter(handler, logger, metrics)

	srv := &http.Server{
		Addr:    cfg.Server.Addr,
		Handler: router,
		// Good practice: enforce timeouts here too
		ReadHeaderTimeout: 5 * time.Second,
	}

	// ---------- Graceful Shutdown ----------
	go func() {
		logger.Info("starting HTTP server", zap.String("addr", cfg.Server.Addr))
		if err := srv.ListenAndServe(); err != nil && err != http.ErrServerClosed {
			logger.Fatal("server failed to start", zap.Error(err))
		}
	}()

	// Wait for interrupt signal
	quit := make(chan os.Signal, 1)
	signal.Notify(quit, os.Interrupt)
	<-quit
	logger.Info("shutdown signal received")

	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()
	if err := srv.Shutdown(ctx); err != nil {
		logger.Error("server forced to shutdown", zap.Error(err))
	}
	logger.Info("server exited gracefully")
}
```

> **Notes**  
> * All resources (DB, Redis, Kafka) are closed via `defer`.  
> * The `signal` package provides graceful termination.  
> * The HTTP server uses a `ReadHeaderTimeout` to mitigate Slowloris attacks.  
> * The logger is `zap.NewProduction()` – JSON output suitable for log aggregation (e.g., Loki, Elasticsearch).  

